    except Exception:
        return tuple()

    if not s:
        return tuple()

    parts = s.split(".")
    nums = []

    for part in parts:
        # Extract the longest leading sequence of digits in the component.
        digit_str = ""
        for ch in part:
            if ch.isdigit():
                digit_str += ch
            else:
