def parse_version(s: str) -> tuple[int, ...]:
    """
    poor man's version comparison

    Parses a version string into a tuple of integers.
    Handles common separators ('.', '-', '_', '+') and an optional
    leading 'v' or 'V'. Non-integer parts are ignored.

    Raises:
        TypeError: if the input is not a string.
    """
    if not isinstance(s, str):
        raise TypeError(f"Expected a string, got {type(s).__name__}")

    s = s.strip()
    if not s:
        return ()

    # Drop an optional leading 'v' or 'V'
    if s[0] in ("v", "V"):
        s = s[1:]

    # Standardise separators to '.'
    for sep in ("-", "_", "+"):
        s = s.replace(sep, ".")

    parts = s.split(".")
    nums = []
    for part in parts:
        if not part:
            continue
        try:
            nums.append(int(part))
        except ValueError:
            # Non-integer component: ignore it
            continue

    return tuple(nums)<|return|>

