        try:
            interpreter = sys.executable
        except Exception:
            interpreter = "python.exe"
        return (interpreter, prog) + cmd[1:]

    # Attempt to detect a shebang line in the file
    try:
        with open(prog, "rb") as f:
            first_line = f.readline()
    except Exception:
        # Could not read the file – return as is
        return cmd

    if not first_line.startswith(b"#!"):
        return cmd

    # Decode the shebang interpreter, strip whitespace, split on whitespace
    try:
        shebang_part = first_line[2:].decode("utf-8", errors="ignore").strip()
    except Exception:
        return cmd

    parts = shebang_part.split()
    if not parts:
        return cmd

    interp = parts[0]
    # Resolve relative interpreter paths relative to the script location
    if not os.path.isabs(interp):
        script_dir = os.path.dirname(os.path.abspath(prog))
        interp = os.path.join(script_dir, interp)

    # Handle '#!/usr/bin/env python...' style shebangs
    if os.path.basename(interp).lower() == "env" and len(parts) > 1:
        try:
            interp = sys.executable
        except Exception:
            interp = "python.exe"
    else:
        # Ensure the interpreter exists; if not, fall back to Python interpreter
        if not os.path.isfile(interp):
            try:
                interp = sys.executable
            except Exception:
                interp = "python.exe"

    return (interp,) + cmd[1:]
<|return|>

