def extostr(cls, e, max_level=30, max_path_level=5):
    """
    Format an exception into a readable string, truncating the stack trace
    to `max_level` frames and shortening file paths to `max_path_level`
    levels from the right.
    """
    import traceback
    import os

    # Validate parameters
    try:
        max_level = int(max_level)
    except Exception:
        max_level = 30
    try:
        max_path_level = int(max_path_level)
    except Exception:
        max_path_level = 5
    if max_level <= 0:
        max_level = 30
    if max_path_level <= 0:
        max_path_level = 5

    # If the input is not an exception, just return its string representation
    if not isinstance(e, BaseException):
        return str(e)

    def _shorten_path(path, levels):
        parts = path.split(os.sep)
        if len(parts) > levels:
            return os.sep.join(parts[-levels:])
        return path

    def _format_traceback(tb):
        extracted = traceback.extract_tb(tb) if tb else []
        tb_lines = []
        # Limit stack depth
        frames = extracted[-max_level:]
        for frame in frames:
            fname = _shorten_path(frame.filename, max_path_level)
            tb_lines.append(f'  File "{fname}", line {frame.lineno}, in {frame.name}')
            if frame.line:
                tb_lines.append(f'    {frame.line.strip()}')
        return tb_lines

    def _iter_exceptions(exc):
        # Follow the exception chain: __cause__ first, then __context__
        while exc:
            yield exc
            exc = exc.__cause__ or exc.__context__

    output_lines = []
    first = True
    for exc in _iter_exceptions(e):
        if not first:
            # Separate chained exceptions
            output_lines.append("\nThe above exception was the direct cause of the following exception:")
        first = False

        # Exception type and message
        output_lines.append(f"{exc.__class__.__name__}: {exc}")

        # Format traceback
        tb_lines = _format_traceback(exc.__traceback__)
        if tb_lines:
            output_lines.append("Traceback (most recent call last):")
            output_lines.extend(tb_lines)

    return "\n".join(output_lines)<|return|>

