    # Helper to recursively flatten iterables that are not strings or bytes
    def _iter(seq):
        try:
            iterator = iter(seq)
        except TypeError:
            # seq is not iterable, just return it
            yield seq
            return
        for item in iterator:
            if isinstance(item, (list, tuple, set, frozenset)) and not isinstance(item, (str, bytes)):
                # Recursively flatten nested containers
                yield from _iter(item)
            else:
                yield item

