    Anything but individual interfaces or implements specs will be expanded.
    """
    if output is None:
        output = []

    # Helper to determine if an object should be expanded
    def _is_expandable(obj):
        return isinstance(obj, (list, tuple, set))

    # Defensive check for invalid input
    if sequence is None:
        return output

    # If sequence itself is not iterable (but not a string), treat it as an atomic item
    if not isinstance(sequence, (list, tuple, set, dict)) and not isinstance(sequence, type):
        output.append(sequence)
