def _should_attempt_c_optimizations():
    """
    Return a true value if we should attempt to use the C optimizations.

    This takes into account whether we're on PyPy and the value of the
    ``PURE_PYTHON`` environment variable, as defined in `_use_c_impl`.
    """
    try:
        import os
        import sys

        # Check for the PURE_PYTHON flag first
        pure_env = os.getenv("PURE_PYTHON")
        if pure_env is not None:
            # Treat a variety of common truthy values as disabling C optimizations
            truthy_vals = {"1", "true", "yes", "y", "on"}
            if pure_env.strip().lower() in truthy_vals:
                return False

        # Next, check if we're running under PyPy, where C extensions may be problematic
        implementation = getattr(sys, "implementation", None)
        if implementation and getattr(implementation, "name", "").lower() == "pypy":
            return False

        # Fallback for older Python versions that may not expose implementation info
        try:
            import platform
            if platform.python_implementation().lower() == "pypy":
                return False
        except Exception:
            pass

        # If none of the conditions above apply, it's safe to try C optimizations
        return True
    except Exception:
        # In the unlikely event of an error, err on the side of caution and disable C
        return False<|return|>

