                    # Treat the whole point as coordinates with no value
                    coords, val = point, None

                # Convert coordinates
                if isinstance(coords, (list, tuple)):
                    coord_strs = [str(c) for c in coords]
                else:
                    coord_strs = [str(coords)]

                # Convert values
                if val is None:
                    line_parts = coord_strs
                else:
                    if isinstance(val, (list, tuple)):
                        val_strs = [str(v) for v in val]
                    elif isinstance(val, str):
                        val_strs = [val]
                    else:
                        val_strs = [str(val)]
                    line_parts = coord_strs + val_strs

                lines.append(separator.join(line_parts))

            if header is not None:
                lines.insert(0, str(header))

            return "\n".join(lines)

        except Exception as exc:
            raise ValueError(f"Error converting graph to CSV: {exc}") from exc<|return|>

