def integral(bins, edges):
    """Compute integral (scale for a histogram).

    *bins* contain values, and *edges* form the mesh
    for the integration.
    Their format is defined in :class:`.histogram` description.
    """
    # Convert inputs to sequences
    try:
        bins_seq = list(bins)
    except Exception as e:
        raise TypeError("bins must be an iterable of numeric values") from e
    try:
        edges_seq = list(edges)
    except Exception as e:
        raise TypeError("edges must be an iterable of numeric values") from e

    # Basic validation
    if len(edges_seq) != len(bins_seq) + 1:
        raise ValueError("edges length must be len(bins) + 1")
    if not bins_seq:
        return 0.0

    # Compute bin widths
    try:
        widths = [float(edges_seq[i+1] - edges_seq[i]) for i in range(len(bins_seq))]
    except Exception as e:
        raise ValueError("edges must contain numeric values") from e

    # Compute integral
    total = 0.0
    for b, w in zip(bins_seq, widths):
        try:
            total += float(b) * w
        except Exception as e:
            raise ValueError("bins must contain numeric values") from e

    return total

