def integral(bins, edges):
    """Compute integral (scale for a histogram).

    *bins* contain values, and *edges* form the mesh
    for the integration.
    Their format is defined in :class:`.histogram` description.
    """
    # Validate inputs and convert to lists
    try:
        bins_list = list(bins)
    except Exception as exc:
        raise TypeError(f"bins must be an iterable of numeric values: {exc}") from exc

    try:
        edges_list = list(edges)
    except Exception as exc:
        raise TypeError(f"edges must be an iterable of numeric values: {exc}") from exc

    # Ensure edges list has at least two elements to form a bin width
    if len(edges_list) < 2:
        raise ValueError("At least two edge values are required to define a bin mesh.")

    # Check that bins length matches edges length - 1
    if len(bins_list) != len(edges_list) - 1:
        raise ValueError(
            f"Number of bins ({len(bins_list)}) must equal number of edges minus one ({len(edges_list) - 1})."
        )

    # Compute widths of each bin
    widths = []
    for i in range(len(edges_list) - 1):
        try:
            low = float(edges_list[i])
            high = float(edges_list[i + 1])
        except Exception as exc:
            raise TypeError(f"Edge values must be numeric: {exc}") from exc
        width = high - low
        if width < 0:
            raise ValueError(f"Edges must be in ascending order; found decreasing pair at indices {i} and {i+1}.")
        widths.append(width)

    # Compute integral
    total = 0.0
    for val, width in zip(bins_list, widths):
        try:
            v = float(val)
        except Exception as exc:
            raise TypeError(f"Bin values must be numeric: {exc}") from exc
        total += v * width

    return total<|return|>

def integral(bins, edges):
    """Compute integral (scale for a histogram).

    *bins* contain values, and *edges* form the mesh
    for the integration.
    Their format is defined in :class:`.histogram` description.
    """
    # Convert inputs to list-like sequences
    try:
        bin_list = list(bins)
    except TypeError:
        raise TypeError("bins must be an iterable of numbers")
    try:
        edge_list = list(edges)
    except TypeError:
        raise TypeError("edges must be an iterable of numbers")

    # Basic length checks
    n_bins = len(bin_list)
    n_edges = len(edge_list)
    if n_edges - 1 != n_bins:
        raise ValueError("Number of edges must be one more than number of bins")

    if n_bins == 0:
        return 0.0

    total = 0.0
    for i, val in enumerate(bin_list):
        try:
            w = float(edge_list[i + 1] - edge_list[i])
            v = float(val)
        except Exception as exc:
            raise TypeError(f"All bin values and edge entries must be numeric: {exc}") from exc
        total += v * w

    return float(total)<|return|>

