    # Determine if seq is iterable (but not a string/bytes)
    try:
        iterator = iter(seq)
        is_iterable = True
    except TypeError:
        is_iterable = False

    if not is_iterable or isinstance(seq, (str, bytes)):
        return _is_fill_request(seq)

    for element in seq:
        try:
            # If element is itself iterable, recurse
            iter(element)
            if is_fill_request_seq(element):
                return True
        except TypeError:
            # Non‑iterable element
            if _is_fill_request(element):
                return True

    return False<|return|>

