def difference(d1, d2, level=-1):
    """
    Return a dictionary with items from *d1* not contained in *d2*.

    *level* sets the maximum depth of recursion. For infinite recursion,
    set that to -1. For level 1, if a key is present both in *d1* and *d2*
    but has different values, it is included into the difference.
    See :func:`intersection` for more details.

    *d1* and *d2* remain unchanged. However, *d1* or some of its
    subdictionaries may be returned directly.
    Make a deep copy of the result when appropriate.

    .. versionadded:: 0.5
       add keyword argument *level*.
    """
    # Basic validation: both must be dictionaries
    if not isinstance(d1, dict) or not isinstance(d2, dict):
        raise TypeError("both d1 and d2 must be dict instances")

    def _diff(a, b, lev):
        """Recursive helper."""
        out = {}
        for k, val in a.items():
            if k not in b:
                # key only in d1: include it
                out[k] = val
            else:
                val2 = b[k]
                # If both values are dicts and recursion allowed, dive deeper
                if isinstance(val, dict) and isinstance(val2, dict) and lev != 0:
                    next_lev = lev if lev == -1 else lev - 1
                    sub = _diff(val, val2, next_lev)
                    if sub:
                        out[k] = sub
                else:
                    # If values differ, include val from d1
                    if val != val2:
                        out[k] = val
        return out

    return _diff(d1, d2, level)
<|return|>

def fill(self, coord, weight=1):
        """
        Fill histogram at *coord* with the given *weight*.

        Coordinates outside the histogram edges are ignored.
        """
        # Validate weight
        try:
            w = float(weight)
        except Exception as exc:
            raise TypeError(f"Weight must be numeric, got {type(weight).__name__}") from exc

        # Ensure `coord` is iterable with the right dimensionality
        try:
            # Handle numpy scalar or python scalar for 1D histograms
            if hasattr(coord, "__iter__") and not isinstance(coord, (str, bytes)):
                coords = list(coord)
            else:
                # Scalar coordinate – treat as 1‑D
                coords = [coord]
        except Exception as exc:
            raise TypeError("Coordinate must be a scalar or iterable of coordinates") from exc

        # Determine dimensionality of the histogram
        ndim = len(self.edges) if hasattr(self, "edges") else getattr(self, "ndim", None)
        if ndim is None:
            raise AttributeError("Histogram object lacks 'edges' or 'ndim' attribute")

        if len(coords) != ndim:
            raise ValueError(f"Coordinate dimension {len(coords)} does not match histogram dimension {ndim}")

        # Determine bin indices for each dimension
        indices = []
        for c, edge in zip(coords, self.edges):
            # Edge must be an array-like of length bins+1
            if not hasattr(edge, "__len__") or len(edge) < 2:
                raise ValueError("Each edges element must be an array-like with at least two bins")
            bin_found = False
            # Linear search – efficient enough for moderate sizes
            for idx in range(len(edge) - 1):
                if edge[idx] <= c < edge[idx + 1]:
                    indices.append(idx)
                    bin_found = True
                    break
            if not bin_found:
                # Coordinate out of bounds – ignore this fill
                return

        # Increment the bin content
        try:
            bin_index_tuple = tuple(indices)
            self.bin_counts[bin_index_tuple] += w
        except Exception as exc:
            # Provide a helpful error message if the underlying storage is unexpected
            raise TypeError("Histogram storage does not support indexing with the computed bin indices") from exc
