def fill(self, coord, weight=1):
        """Fill histogram at *coord* with the given *weight*.

        Coordinates outside the histogram edges are ignored.
        """
        import numpy as np

        # ---- Input validation ----
        try:
            coord_arr = np.asarray(coord, dtype=float)
        except Exception as exc:
            raise TypeError(f"coord must be array‑like, got {type(coord)}") from exc

        if coord_arr.ndim != 1:
            raise ValueError(f"coord must be one‑dimensional, got {coord_arr.shape}")

        ndim = len(self.edges) if hasattr(self, "edges") else 0
        if ndim == 0:
            raise AttributeError("Histogram instance has no 'edges' attribute")
        if coord_arr.size != ndim:
            raise ValueError(f"coord dimensionality ({coord_arr.size}) does not match histogram dimension ({ndim})")

        # ---- Weight validation ----
        try:
            w = float(weight)
        except Exception as exc:
            raise ValueError(f"weight must be a numeric value, got {type(weight)}") from exc

        # ---- Find bin indices ----
        indices = []
        for dim, edge in enumerate(self.edges):
            # edge should be sorted; use searchsorted
            idx = np.searchsorted(edge, coord_arr[dim], side="right") - 1
            # index validity check
            if idx < 0 or idx >= len(edge) - 1:
                return  # reject coordinate outside edges
            indices.append(idx)

        # ---- Update histogram counts ----
        # Support numpy array or dict-like counts
        if isinstance(getattr(self, "counts", None), np.ndarray):
            try:
                self.counts[tuple(indices)] += w
            except Exception as exc:
                raise RuntimeError(f"Failed to update counts array: {exc}") from exc
        else:
            # assume a dictionary mapping bin tuples to weight sums
            key = tuple(indices)
            existing = getattr(self, "counts", {}).get(key, 0.0)
            try:
                new_val = existing + w
            except Exception as exc:
                raise RuntimeError(f"Failed to add weight to existing value: {exc}") from exc
            self.counts[key] = new_val

        return None <|return|>

def _validate_labels(labels):
    """
    Check that keys and values in the given labels match against their corresponding
    restrictions.

    Args:
        labels (dict): the different labels to validate.

    Raises:
        ValidationError: if any of the keys and labels does not match their respective
            restrictions. The error contains as message the list of all errors
            which occurred in the labels. Each element of the list is a dictionary with
            one key-value pair:
            - key: the label key or label value for which an error occurred.
            - value: the error message.
    """
    messages = []

    if not isinstance(labels, dict):
        # If the input is not a dictionary, report a single error.
        messages.append({"labels": "labels must be a dictionary"})
        raise ValidationError(messages)

    # Define allowed characters for keys and values.
    allowed_chars = set("abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789._-")

    def _is_valid_text(text):
        """Return True if text is a non-empty string containing only allowed characters."""
        if not isinstance(text, str):
            return False
        if not text:
            return False
        return all(ch in allowed_chars for ch in text)

    for key, value in labels.items():
        # Validate key
        if not isinstance(key, str):
            messages.append({str(key): "expected string or bytes-like object"})
        elif not _is_valid_text(key):
            messages.append({key: f"Label key '{key}' does not match the allowed pattern"})

        # Validate value
        if isinstance(value, list):
            for v in value:
                if not isinstance(v, str):
                    messages.append({str(v): "expected string or bytes-like object"})
                elif not _is_valid_text(v):
                    messages.append({v: f"Label value '{v}' does not match the allowed pattern"})
        else:
            if not isinstance(value, str):
                messages.append({str(value): "expected string or bytes-like object"})
            elif not _is_valid_text(value):
                messages.append({value: f"Label value '{value}' does not match the allowed pattern"})

    if messages:
        raise ValidationError(messages)<|return|>

def validate_value(value):
    """Validate the given value against the corresponding regular expression.

    Args:
        value: the string to validate

    Raises:
        ValidationError: if the given value is not conform to the regular expression.
    """
    # Attempt to retrieve a global regex pattern to validate against.
    pattern_str = globals().get("VALIDATION_REGEX", None)
    if not pattern_str:
        # No pattern specified; nothing to validate.
        return
    try:
        import re
        pattern = re.compile(pattern_str)
    except Exception:
        # If the pattern is invalid, skip validation.
        return

    if value is None:
        raise ValidationError("Value cannot be None.")
    if not isinstance(value, str):
        raise ValidationError(f"Expected string, got {type(value).__name__}.")

    if not pattern.fullmatch(value):
        raise ValidationError(
            f"Value '{value}' does not match the required pattern."
        )<|return|>

def generate_default_observer_schema_dict(manifest_dict, first_level=False):
    """
    Generate a default observer schema dictionary from a Kubernetes resource manifest.

    Args:
        manifest_dict (dict): Partial Kubernetes resources.
        first_level (bool, optional):
            If True, indicates that the dictionary represents the whole observer
            schema of a Kubernetes resource.

    Returns:
        dict: Generated partial observer_schema.
    """
    # Validate input
    if not isinstance(manifest_dict, dict):
        raise TypeError("manifest_dict must be a dictionary")

    # Identifying fields to preserve in the first level
    identifying_fields = {"apiVersion", "kind", "metadata"}

    result = {}
    for key, value in manifest_dict.items():
        # Preserve identifying fields at the top level
        if first_level and key in identifying_fields:
            result[key] = value
            continue

        # Process dictionaries recursively
        if isinstance(value, dict):
            result[key] = generate_default_observer_schema_dict(value, first_level=False)
            continue

        # Process lists recursively
        if isinstance(value, list):
            processed_list = []
            for item in value:
                if isinstance(item, dict):
                    processed_list.append(generate_default_observer_schema_dict(item, first_level=False))
                elif isinstance(item, list):
                    # Recursively process nested lists
                    processed_list.append(
                        [
                            generate_default_observer_schema_dict(sub_item, first_level=False)
                            if isinstance(sub_item, dict)
                            else (
                                (
                                    [
                                        generate_default_observer_schema_dict(sub_sub_item, first_level=False)
                                        if isinstance(sub_sub_item, dict)
                                        else None
                                        for sub_sub_item in sub_item
                                    ]
                                )
                                if isinstance(sub_item, list)
                                else None
                            )
                            for sub_item in item
                        ]
                    )
                else:
                    processed_list.append(None)
            result[key] = processed_list
            continue

        # Non-dict and non-list values are replaced with None
        result[key] = None

    return result<|return|>

def update_last_applied_manifest_list_from_resp(
    last_applied_manifest, observer_schema, response
):
    """Update a partial ``last_applied_manifest`` (list) recursively from a partial Kubernetes response.

    Args:
        last_applied_manifest (list): The list to be updated in place.
        observer_schema (list): List describing the fields that should appear in ``last_applied_manifest``.
        response (list): The Kubernetes API response to merge from.

    Returns:
        list: The updated ``last_applied_manifest``.
    """
    # Basic validation
    if not isinstance(observer_schema, list):
        raise TypeError("observer_schema must be a list")
