        if not hasattr(app.spec, "observer_schema") or app.spec.observer_schema is None:
            app.spec.observer_schema = {}

        # Manifest could be a list or a dict of resources.
        resources = []
        if isinstance(manifest, list):
            resources = manifest
        elif isinstance(manifest, dict):
            # Some manifests are keyed by resource name; take the values
            resources = list(manifest.values())
        else:
            # Unsupported manifest type; skip
            return

        for res in resources:
            if not isinstance(res, dict):
                continue

            kind = res.get("kind")
            api_version = res.get("apiVersion")
            if not kind or not api_version:
                continue

            key = f"{api_version}.{kind}"

            # Check whether the resource already specifies a custom observer schema.
            # Custom schemas can be defined via annotations or a dedicated field.
            has_custom = False
            annotations = res.get("metadata", {}).get("annotations", {})
            if isinstance(annotations, dict) and "krake.io/observer-schema" in annotations:
                has_custom = True
            if res.get("spec", {}).get("observer_schema") is not None:
                has_custom = True

            if has_custom:
                continue

            # Build a very simple default schema based on the keys present in
            # the resource's spec. The goal is to provide a minimal object that
            # reflects the resource's fixed properties.
            default_schema = {
                "type": "object",
                "properties": {},
                "additionalProperties": True,
            }

            spec = res.get("spec", {})
            if isinstance(spec, dict):
                for field, val in spec.items():
                    # Infer a basic JSON type
