                    elif isinstance(val, int):
                        field_type = "integer"
                    elif isinstance(val, float):
                        field_type = "number"
                    elif isinstance(val, list):
                        field_type = "array"
                    elif isinstance(val, dict):
                        field_type = "object"
                    default_schema["properties"][field] = {"type": field_type}

