        if not os.path.exists(p):
            return False

        # An OCFL object must contain a .ocfl_object.json descriptor.
        root_desc = os.path.join(p, ".ocfl_object.json")
        if os.path.isfile(root_desc):
            # Optionally verify the JSON is readable.
            try:
                with open(root_desc, "rb") as f:
                    # Quick byte check to ensure it's not empty.
                    if not f.read(1):
                        return False
            except Exception:
                return False
            return True

        # If the descriptor isn't found, fall back to the legacy "objects" directory layout.
        objects_dir = os.path.join(p, "objects")
        if not os.path.isdir(objects_dir):
            return False

        # Look for an ocfl_version file; if present, its content must be a valid version number.
        ver_file = os.path.join(p, ".ocfl_version")
        if os.path.isfile(ver_file):
            try:
                with open(ver_file, "r", encoding="utf-8") as f:
                    version = f.read().strip()
                if version not in {"1", "2"}:
                    return False
            except Exception:
                return False

        # Perform a minimal sanity check: at least one contents dir should exist.
        # The naming convention is "{base}/objects/{SHA1}/{1..7}/content".
        # We'll accept a single content directory if present.
        contents_found = False
        for entry in os.listdir(objects_dir):
            if entry.endswith(".contents"):
                continue
            obj_dir = os.path.join(objects_dir, entry)
            if os.path.isdir(obj_dir):
                contents_found = True
                break
        if not contents_found:
            return False

