        the specification version. In the case that there is no type value or it isn't
        valid, then other tests will be based on the version given in self.spec_version.
        """
        # Basic type checks for input arguments
        if not isinstance(inventory, dict):
            raise TypeError(f"Expected inventory to be a dict, got {type(inventory).__name__}")

        if not isinstance(extract_spec_version, bool):
            raise TypeError(f"extract_spec_version must be a bool, got {type(extract_spec_version).__name__}")

        # Determine the specification version
        spec_version = None
        if extract_spec_version:
            type_value = inventory.get("type")
            if isinstance(type_value, str):
                # Expect format: SPEC_v<digit>
                if type_value.startswith("SPEC_v") and type_value[6:].isdigit():
                    spec_version = type_value[6:]
            # If extraction failed, fall back to self.spec_version
            if spec_version is None:
                spec_version = getattr(self, "spec_version", None)

        # If not extracting or extraction failed, use self.spec_version
        if spec_version is None:
            spec_version = getattr(self, "spec_version", None)

        if spec_version is None:
            raise ValueError("Specification version could not be determined")

        # Store extracted spec_version back to self for future use
        try:
            setattr(self, "spec_version", spec_version)
        except Exception as exc:
            # ignore if attribute can't be set
            pass

        # Define simple required keys per spec version
        required_keys_by_version = {
            "1": ["name", "template"],
            "2": ["name", "template", "variables"],
            "3": ["name", "template", "variables", "nodes"],
        }

        required_keys = required_keys_by_version.get(spec_version)
        if required_keys is None:
            raise ValueError(f"Unsupported specification version: {spec_version}")

        missing_keys = [k for k in required_keys if k not in inventory]
        if missing_keys:
            raise ValueError(f"Inventory missing required keys for spec v{spec_version}: {missing_keys}")

        # Additional simple validations depending on spec version
        try:
            if not isinstance(inventory["name"], str) or not inventory["name"]:
                raise ValueError("The 'name' field must be a non-empty string")

            if not isinstance(inventory["template"], str) or not inventory["template"]:
                raise ValueError("The 'template' field must be a non-empty string")

            if spec_version in ["2", "3"]:
                vars_field = inventory.get("variables")
                if not isinstance(vars_field, dict):
                    raise ValueError("The 'variables' field must be a dictionary")

            if spec_version == "3":
                nodes_field = inventory.get("nodes")
                if not isinstance(nodes_field, list) or not nodes_field:
                    raise ValueError("The 'nodes' field must be a non-empty list")

        except KeyError as exc:
            raise ValueError(f"Missing required field: {exc}") from exc
        except Exception as exc:
            raise ValueError(f"Invalid inventory: {exc}") from exc

        # If all checks pass, return True
        return True<|return|>

def validate(self, inventory, extract_spec_version=False):
