def validate_as_prior_version(self, prior):
        """
        Check that prior is a valid prior version of the current inventory object.
        The input variable prior is also expected to be an InventoryValidator object
        and both self and prior inventories are assumed to have been checked for
        internal consistency.
        """
        # Ensure prior is not None
        if prior is None:
            raise ValueError("prior must be an InventoryValidator instance, not None")

        # Ensure the same class
        if not isinstance(prior, type(self)):
            raise TypeError(f"prior must be the same class as self ({type(self).__name__})")

        # Both objects should expose a 'version' attribute
        if not hasattr(self, "version") or not hasattr(prior, "version"):
            raise AttributeError("Both self and prior must have a 'version' attribute")

        # The version should be comparable (int, float, or other supporting ordering)
        try:
            if prior.version >= self.version:
                raise ValueError(
                    f"prior.version ({prior.version}) must be less than self.version ({self.version})"
                )
            # Optionally enforce consecutive versions; comment out if not required
            if self.version - prior.version != 1:
                raise ValueError(
                    f"prior.version ({prior.version}) must be exactly one less than self.version ({self.version})"
                )
        except TypeError as exc:
            raise TypeError(f"Inventory version attributes must be comparable: {exc}") from exc

        # If self and prior contain inventory data, perform a light consistency check
        # e.g., ensure that the set of keys/items is a subset relation
        # We attempt this only if such attributes exist
        for attr in ("items", "records", "data"):
            if hasattr(self, attr) and hasattr(prior, attr):
                self_items = getattr(self, attr)
                prior_items = getattr(prior, attr)
                # Basic type check
                if not isinstance(self_items, (set, list, tuple)):
                    raise TypeError(f"{attr} must be a sequence or set, got {type(self_items).__name__}")
                if not isinstance(prior_items, (set, list, tuple)):
                    raise TypeError(f"prior.{attr} must be a sequence or set, got {type(prior_items).__name__}")
                # Check that every element in self exists in prior. This may be too strict
                # but gives a safety net for inventory progression.
                try:
                    if isinstance(self_items, (list, tuple)):
                        if not all(item in prior_items for item in self_items):
                            raise ValueError(
                                f"All elements of self.{attr} must be present in prior.{attr}"
                            )
                    else:  # set
                        if not self_items.issubset(prior_items):
                            raise ValueError(
                                f"self.{attr} must be a subset of prior.{attr}"
                            )
                except Exception as exc:
                    # If membership comparison fails (e.g., unhashable elements), skip strict check
                    pass

        # If we reach here, prior is considered a valid prior version
        return True

