    """Get a map of logical paths in state to files on disk for version in inventory.

    Returns a dictionary: logical_path_in_state -> set(content_files)

    The set of content_files may includes references to duplicate files in
    later versions than the version being described.
    """
    # Basic validation
    if inventory is None:
        return {}
    if not isinstance(inventory, dict):
        raise TypeError("inventory must be a dictionary")
    if not isinstance(version, (str, int)):
        raise TypeError("version must be a string or int")
    version_key = str(version)

    result = {}

    for logical_path, version_map in inventory.items():
        # Each logical_path should map to a dict of version -> file(s)
        if not isinstance(version_map, dict):
            continue

        # Skip paths that don't exist in the requested version
        if version_key not in version_map:
            continue

        # Helper to add files to the result set
        def add_file_set(mapping, ver, files_collection):
            files = mapping.get(ver)
            if files is None:
                return
            # If files is a list/tuple, iterate; otherwise treat as single entry
            if isinstance(files, (list, tuple)):
                for f in files:
                    if isinstance(f, str):
                        files_collection.add(f)
            elif isinstance(files, str):
                files_collection.add(files)

        # Prepare the set for this logical path
        path_set = result.setdefault(logical_path, set())

        # Add the target version's files
        add_file_set(version_map, version_key, path_set)

        # Add files from later versions (if any)
        for other_version, _ in version_map.items():
            if other_version == version_key:
                continue
            try:
                # Simple string/int comparison; if fails, skip this entry
                if other_version > version_key:
                    add_file_set(version_map, other_version, path_set)
            except Exception:
                continue

    return result<|return|>

