            raise ValueError(f"Fixity key '{key}' must be a non-empty string")

    # Gather all file references that appear under typical keys
    referenced_files = set()

    def _collect_from(obj):
        if isinstance(obj, dict):
            for k, v in obj.items():
                if k in {"files", "file", "file_path", "file_ref"}:
                    if isinstance(v, str):
                        referenced_files.add(v)
                    elif isinstance(v, (list, tuple, set)):
                        referenced_files.update(v)
                    else:
