def validate_fixity(self, fixity, manifest_files):
    """Validate fixity block in inventory.

    Check the structure of the fixity block and makes sure that only files
    listed in the manifest are referenced.
    """
    # Basic type checks for the inputs
    if not isinstance(fixity, dict):
        raise ValueError("Fixity block must be a dictionary.")
    if not isinstance(manifest_files, (list, set, tuple)):
        raise ValueError("Manifest files must be a list, set, or tuple.")

    # Required keys in the fixity block
    required_keys = {"type", "checksum", "files"}
    missing_keys = required_keys - fixity.keys()
    if missing_keys:
        raise ValueError(f"Fixity block missing required keys: {', '.join(sorted(missing_keys))}")

    # Validate checksum type, value, and files list
    ftype = fixity["type"]
    fchecksum = fixity["checksum"]
    ffiles = fixity["files"]

    if not isinstance(ftype, str) or not ftype:
        raise ValueError("Fixity 'type' must be a non-empty string.")
    allowed_types = {"sha1", "sha256", "md5"}
    if ftype.lower() not in allowed_types:
        raise ValueError(f"Unsupported checksum type '{ftype}'. "
                         f"Supported types are: {', '.join(sorted(allowed_types))}")

    if not isinstance(fchecksum, str) or not fchecksum:
        raise ValueError("Fixity 'checksum' must be a non-empty string.")

    if not isinstance(ffiles, (list, tuple, set)):
        raise ValueError("Fixity 'files' must be a list, tuple, or set of file paths.")

    # Ensure all referenced files are present in the manifest
    manifest_set = set(manifest_files)
    for entry in ffiles:
        if not isinstance(entry, str):
            raise ValueError(f"Each entry in 'files' must be a string, got {type(entry).__name__}.")
        if entry not in manifest_set:
            raise ValueError(f"File '{entry}' referenced in fixity block is not present in manifest.")

    return True<|return|>

def validate_fixity(self, fixity, manifest_files):
    """
    Validate the structure of a fixity block and ensure that it only references files
    that appear in the provided *manifest_files* collection.

    Parameters
    ----------
    fixity : Mapping
        Dictionary representation of the fixity block from the inventory.
    manifest_files : Iterable[str]
        Collection of file paths that are listed in the current manifest.

    Raises
    ------
    ValueError
        If the fixity block is malformed, or if it refers to files not present
        in *manifest_files*.
    """
    if not isinstance(fixity, dict):
        raise ValueError("Fixity block must be a dictionary")

    # Normalise the set of known file names
    try:
        known_files = set(manifest_files)
    except TypeError as exc:
        raise ValueError("manifest_files must be an iterable of file paths") from exc

    # Allowed top‑level keys for the fixity block
    allowed_keys = {"algorithm", "algorithm_name", "files", "fileChecksums", "checksums"}
    # If the block contains keys other than the allowed ones raise a warning
    unknown_keys = set(fixity) - allowed_keys
    if unknown_keys:
        raise ValueError(f"Fixity block contains unsupported keys: {', '.join(sorted(unknown_keys))}")

    # Determine how the file references are stored
    # 1. "files" key contains a list of entries, e.g. [{"file": "...", "value": "..."}]
    if "files" in fixity:
        files_val = fixity["files"]
        if not isinstance(files_val, (list, tuple)):
            raise ValueError('The "files" key must map to a list')
        for idx, entry in enumerate(files_val):
            if not isinstance(entry, dict):
                raise ValueError(f'Entry {idx} in "files" list must be a dictionary')
            if "file" not in entry:
                raise ValueError(f'Entry {idx} in "files" list missing "file" key')
            file_name = entry["file"]
            if not isinstance(file_name, str):
                raise ValueError(f'File name in entry {idx} must be a string')
            if file_name not in known_files:
                raise ValueError(f'Fixity references unknown file "{file_name}"')
            # Optionally check that a checksum value is provided
            if "value" not in entry:
                raise ValueError(f'Entry {idx} in "files" list missing "value" key')
    # 2. "fileChecksums" or "checksums" key maps file names to checksum strings
    elif "fileChecksums" in fixity or "checksums" in fixity:
        key_name = "fileChecksums" if "fileChecksums" in fixity else "checksums"
        cs_dict = fixity[key_name]
        if not isinstance(cs_dict, dict):
            raise ValueError(f'The "{key_name}" key must map to a dictionary')
        for file_name in cs_dict:
            if not isinstance(file_name, str):
                raise ValueError(f'File name in "{key_name}" dictionary must be a string')
            if file_name not in known_files:
                raise ValueError(f'Fixity references unknown file "{file_name}"')
            # Optional: check that the checksum string is present and not empty
            value = cs_dict[file_name]
            if not isinstance(value, str) or not value:
                raise ValueError(f'Checksum value for "{file_name}" must be a non‑empty string')
    # 3. Legacy case: the fixity block is itself a mapping file→checksum
    elif len(fixity) > 0:
        for file_name in fixity:
            if not isinstance(file_name, str):
                raise ValueError(f'File name "{file_name}" in fixity block must be a string')
            if file_name not in known_files:
                raise ValueError(f'Fixity references unknown file "{file_name}"')
            value = fixity[file_name]
            if not isinstance(value, str) or not value:
                raise ValueError(f'Checksum value for "{file_name}" must be a non‑empty string')
    else:
        # Empty fixity block – acceptable, but warn if this seems unintended
        pass
    # If we reach here, the block is considered valid; nothing to return
    return None<|return|>

