def _explore_folder(folder):
    """
    Get packages' data from folder

    Groups files by their XML basename and returns data in dict format.

    Parameters
    ----------
    folder : str
        Folder of the package
    Returns
    -------
    dict
    """
    try:
        if not isinstance(folder, str):
            raise TypeError("folder must be a string path")

        abs_folder = os.path.abspath(folder)
        if not os.path.isdir(abs_folder):
            raise ValueError(f"Folder not found or not a directory: {folder}")

        entries = os.listdir(abs_folder)

        # First gather all XML files
        xml_map = {}  # base name -> xml file path
        for name in entries:
            path = os.path.join(abs_folder, name)
            if not os.path.isfile(path):
                continue
            if name.lower().endswith('.xml'):
                base = os.path.splitext(name)[0]
                xml_map[base] = path

        # Prepare result dict: base -> {'xml': path, 'files': [other_file_paths]}
        result = {base: {'xml': xml_path, 'files': []} for base, xml_path in xml_map.items()}

        # Now associate other files (non-xml) to the appropriate base
        for name in entries:
            path = os.path.join(abs_folder, name)
            if not os.path.isfile(path):
                continue
            if name.lower().endswith('.xml'):
                continue
            base = os.path.splitext(name)[0]
            if base in result:
                result[base]['files'].append(path)

        return result

    except Exception as exc:
        raise RuntimeError(f"Failed to explore folder '{folder}': {exc}") from exc<|return|>

