def pretty(self, indent=0, debug=False):
    """
    Return a pretty formatted representation of self.
    Parameters
    ----------
    indent : int, default 0
        Number of spaces to indent each nested level.
    debug : bool, default False
        If True, include type information for each value.
    Returns
    -------
    str
        A human‑readable string representation of the object.
    """
    # Ensure indent is a non‑negative integer
    try:
        indent = int(indent)
        if indent < 0:
            indent = 0
    except Exception:
        indent = 0

    visited = set()

    def _space(level):
        return ' ' * (level * indent)

    def _pretty(obj, level):
        # Detect recursion
        obj_id = id(obj)
        if obj_id in visited:
            return '... (recursive reference)'

        # Simple immutable types
        if isinstance(obj, (int, float, bool, type(None))):
            if debug:
                return f'{repr(obj)} (type: {type(obj).__name__})'
            return repr(obj)

        if isinstance(obj, str):
            if debug:
                return f'{repr(obj)} (type: str)'
            return repr(obj)

        # Containers
        if isinstance(obj, list):
            visited.add(obj_id)
            lines = ['[']
            for i, item in enumerate(obj):
                lines.append(f"{_space(level+1)}{i}: {_pretty(item, level+1)}")
            lines.append(f"{_space(level)}]")
            visited.remove(obj_id)
            return '\n'.join(lines)

        if isinstance(obj, tuple):
            visited.add(obj_id)
            lines = ['(']
            for i, item in enumerate(obj):
                lines.append(f"{_space(level+1)}{i}: {_pretty(item, level+1)}")
            lines.append(f"{_space(level)})")
            visited.remove(obj_id)
            return '\n'.join(lines)

        if isinstance(obj, set):
            visited.add(obj_id)
            lines = ['{']
            for i, item in enumerate(sorted(obj, key=lambda x: repr(x))):
                lines.append(f"{_space(level+1)}{i}: {_pretty(item, level+1)}")
            lines.append(f"{_space(level)}}}")
            visited.remove(obj_id)
            return '\n'.join(lines)

        if isinstance(obj, dict):
            visited.add(obj_id)
            lines = ['{']
