def get_versions():
    """Get version information or return default if unable to do so."""
    # Try to obtain the distribution package name from the module context
    pkg_name = __package__ or __name__
    # If the name contains dots, use the top‑level package part
    top_pkg = pkg_name.split('.')[0] if pkg_name else ""

    # First attempt: use the standard importlib.metadata (Python 3.8+)
    try:
        # Import inside the function to avoid importing on module load
        from importlib.metadata import distribution
        if top_pkg:
            # distribution throws if the package is not found
            return distribution(top_pkg).version
        else:
            raise ValueError
    except Exception:
        pass

    # Second attempt: fall back to the older pkg_resources (easily available)
    try:
        import pkg_resources
        if top_pkg:
            return pkg_resources.get_distribution(top_pkg).version
        else:
            raise ValueError
    except Exception:
        # If all attempts fail, return a safe default
        return "0.0.0"
