def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""
    # Validate input types
    if not isinstance(commands, (str, list)):
        raise TypeError("commands must be a string or a list of strings")
    if not isinstance(args, (list, tuple)):
        raise TypeError("args must be a list or tuple of strings")

    # Build the command list
    if isinstance(commands, str):
        cmd = [commands]
    else:
        if not all(isinstance(c, str) for c in commands):
            raise TypeError("all elements of commands list must be strings")
        cmd = list(commands)

    if not all(isinstance(a, str) for a in args):
        raise TypeError("all elements of args must be strings")
    cmd.extend(args)

    # Verbose output
    if verbose:
        print("Running command:", " ".join(cmd))

    try:
        # Run the command
        result = subprocess.run(
            cmd,
            cwd=cwd,
            env=env,
            stdout=subprocess.PIPE,
            stderr=subprocess.DEVNULL if hide_stderr else subprocess.PIPE,
            text=True,
            check=True
        )
    except FileNotFoundError as e:
        raise RuntimeError(f"Command not found: {cmd[0]}") from e
    except subprocess.CalledProcessError as e:
        stderr = e.stderr if not hide_stderr else ""
        raise RuntimeError(
            f"Command '{' '.join(e.cmd)}' failed with exit code {e.returncode}. "
            f"Stderr: {stderr}"
        ) from e
    except Exception as e:
        raise RuntimeError(f"Error running command '{' '.join(cmd)}': {e}") from e

    return result<|return|>

def register_vcs_handler(vcs, method):
