def next_version(version):
    """Next version identifier following existing pattern.

    Must deal with both zero-prefixed and non-zero prefixed versions.
    """
    if not isinstance(version, str):
        raise TypeError("version must be a string")
    if not version:
        raise ValueError("version string cannot be empty")
    if not version.isdigit():
        raise ValueError(f"version '{version}' must contain only digits")

    try:
        num = int(version)
    except Exception as exc:
        raise ValueError(f"invalid numeric value: {exc}") from exc

    next_num = num + 1
    orig_len = len(version)
    next_str = str(next_num)

    if version.startswith("0") and len(next_str) < orig_len:
        next_str = next_str.rjust(orig_len, "0")

    return next_str<|return|>

