def validate_version_inventories(self, version_dirs):
        """
        Each version SHOULD have an inventory up to that point.

        Also keep a record of any content digests different from those in the root inventory
        so that we can also check them when validating the content.

        version_dirs is an array of version directory names and is assumed to be in
        version sequence (1, 2, 3...).
        """
        # Basic input validation
        if not isinstance(version_dirs, (list, tuple)):
            raise TypeError("version_dirs must be a list or tuple of directory names")
        for v in version_dirs:
            if not isinstance(v, str):
                raise TypeError("Each version directory name must be a string")

        # Ensure the root inventory is present and is a dict
        if not hasattr(self, 'root_inventory') or not isinstance(self.root_inventory, dict):
            raise AttributeError("Missing or invalid root_inventory attribute")

        # Ensure the base path attribute is present
        if not hasattr(self, 'base_path'):
            raise AttributeError("Missing base_path attribute")

        # Prepare a dict to record any digest discrepancies
        self.discrepancies = {}

        # Maintain a running set of known files up to the current version
        cumulative_files = set(self.root_inventory.keys())

        for idx, version_dir in enumerate(version_dirs, start=1):
            inventory_path = os.path.join(self.base_path, version_dir, "inventory.json")
            if not os.path.exists(inventory_path):
                raise FileNotFoundError(f"Inventory not found for version directory '{version_dir}' "
                                        f"(expected at {inventory_path})")

            try:
                with open(inventory_path, 'r', encoding='utf-8') as f:
                    data = json.load(f)
            except Exception as e:
                raise ValueError(f"Failed to load inventory at {inventory_path}: {e}") from e

            if not isinstance(data, dict):
                raise ValueError(f"Inventory '{inventory_path}' must be a JSON object mapping paths to digests")

            # Validate that all files from previous versions are present
            current_files = set(data.keys())
            missing = cumulative_files - current_files
            if missing:
                raise ValueError(f"Version {idx} inventory '{inventory_path}' is missing files: "
                                 f"{sorted(missing)}")

            # Compare digests with the root inventory and record discrepancies
            for path, digest in data.items():
                root_digest = self.root_inventory.get(path)
                if root_digest is not None and digest != root_digest:
                    self.discrepancies.setdefault(path, []).append({
                        'version': version_dir,
                        'new_digest': digest,
                        'root_digest': root_digest
                    })

            # Update the cumulative set with any new files that appeared in this version
            cumulative_files.update(current_files)
        # Method returns None implicitly; self.discrepancies holds the discrepancy data.<|return|>

def find_path_type(path):
    """Return a string indicating the type of thing at the given path.

    Return values:
        'root'   - looks like an OCFL Storage Root
        'object' - looks like an OCFL Object
        'file'   - a file, might be an inventory
        other string explains error description

    Looks only at "0=*" Namaste files to determine the directory type.
    """
    try:
        import os
        # Resolve any symlinks
        real_path = os.path.realpath(path)
    except Exception as e:
        return f"failed to resolve path: {e}"

    try:
        if not os.path.exists(real_path):
            return f"path does not exist: {path}"
    except Exception as e:
        return f"cannot access path: {e}"

    try:
        if os.path.isfile(real_path):
            return "file"
        if os.path.isdir(real_path):
            try:
                entries = os.listdir(real_path)
            except Exception as e:
                return f"unable to list directory '{path}': {e}"

            # Object detection: presence of any file beginning with '0='
            for entry in entries:
                if entry.startswith("0="):
                    return "object"

            # Root detection: contains an 'objects' subdirectory
            if "objects" in entries and os.path.isdir(os.path.join(real_path, "objects")):
                return "root"

            # Fallback: default to root if it has any subdirectories (common for storage roots)
            for entry in entries:
                if os.path.isdir(os.path.join(real_path, entry)):
                    return "root"

            # If directory but no 0= or objects subdir
            return f"directory without recognizable OCFL structure: {path}"
    except Exception as e:
        return f"unexpected error while examining '{path}': {e}"
    return f"unknown status for path: {path}"
