            for entry in os.scandir(dir_path):
                if entry.is_file() and entry.name.startswith("0="):
                    return True
        except PermissionError:
            return False
        return False

    # Detect 'root' by presence of 'objects' subdirectory
    objects_dir = os.path.join(path, "objects")
    if os.path.isdir(objects_dir):
        return "root"

