    Given a nested borgmatic configuration data structure as a list of tuples in the form of:

        (
            ruamel.yaml.nodes.ScalarNode as a key,
            ruamel.yaml.nodes.MappingNode or other Node as a value,
        ),

    deep merge any node values corresponding to duplicate keys and return the result. If
    there are colliding keys with non-MappingNode values (e.g., integers or strings), the last
    of the values wins.
    '''

    # Helper to merge two MappingNode instances
    def merge_map_nodes(m1, m2):
        """Merge m2 into m1 and return the merged MappingNode."""
        # If tags differ, just return m2 (fallback to last value)
        if getattr(m1, 'tag', None) != getattr(m2, 'tag', None):
            return m2

        # Build index for existing keys in m1
        val1 = list(m1.value) if hasattr(m1, 'value') else []
        key_to_index = {}
        for idx, (k, _) in enumerate(val1):
            try:
                key_to_index[k.value] = idx
            except AttributeError:
                key_to_index[str(k)] = idx

        # Process entries from m2
        val2 = list(m2.value) if hasattr(m2, 'value') else []
        for k2, v2 in val2:
            key_val = getattr(k2, 'value', str(k2))
            if key_val in key_to_index:
                i = key_to_index[key_val]
                _, v1 = val1[i]
                if isinstance(v1, type(m2)) and isinstance(v2, type(m2)):
                    # Recursive merge for nested MappingNodes
                    val1[i] = (k2, merge_map_nodes(v1, v2))
                else:
                    # Override non-mapping values
                    val1[i] = (k2, v2)
            else:
                val1.append((k2, v2))
                key_to_index[key_val] = len(val1) - 1

        # Update m1's value and return
        m1.value = val1
        return m1

    result = []
    key_to_index = {}

    for k, v in nodes:
        # Retrieve key representation for mapping
        try:
            key_rep = k.value
        except AttributeError:
            key_rep = str(k)

        if key_rep in key_to_index:
            idx = key_to_index[key_rep]
            existing_key, existing_val = result[idx]

            if isinstance(existing_val, type(v)) and isinstance(v, type(v)):
                # Both are MappingNode-like
                merged_val = merge_map_nodes(existing_val, v)
