def bash_completion():
    '''
    Return a bash completion script for the borgmatic command. Produce this by introspecting
    borgmatic's command-line argument parsers.
    '''
    try:
        # Import borgmatic package and attempt to locate its main parser
        import borgmatic
    except Exception:
        # If borgmatic is not importable, return a generic placeholder script
        return """#!/usr/bin/env bash
# Generic bash completion script for borgmatic
_borgmatic_completion() {
    local cur prev words cword
    COMPREPLY=()
}
complete -F _borgmatic_completion borgmatic"""
    try:
        # Try to import the module that defines the main parser
        for module_name in ('borgmatic.__main__', 'borgmatic.cli'):
            try:
                mod = __import__(module_name, fromlist=['parser'])
                parser = getattr(mod, 'parser', None)
                if parser:
                    break
            except Exception:
                continue
        else:
            parser = None

        if parser:
            # Gather top‑level subcommand names if the parser uses subparsers
            subcommands = []
            for action in parser._actions:
                if hasattr(action, 'choices') and action.choices:
                    subcommands.extend(action.choices)
                    break
            # Dynamically build a Bash array of these subcommands
            subcmds = " ".join(subcommands) if subcommands else ""
            # Build a minimal Bash completion function for borgmatic
            script = f"""#!/usr/bin/env bash
_borgmatic_completion() {{
    local cur prev words cword
    _init_completion -s -i || return
    COMPREPLY=()
    case "$prev" in
        borgmatic) COMPREPLY=($(compgen -W "{subcmds}" -- $cur));;
        *) COMPREPLY=($(compgen -W "{subcmds}" -- $cur));;
    esac
}}
complete -F _borgmatic_completion borgmatic"""
            return script
    except Exception:
        pass

    # Fallback to a very simple completion script if everything else failed
    return """#!/usr/bin/env bash
# Generic bash completion script for borgmatic
