def _replace_url_args(url, url_args):
    """Replace any custom string URL items with values in args"""
    if not isinstance(url, str):
        return url
    if url_args is None:
        return url
    try:
        result = url
        if isinstance(url_args, dict):
            for key, val in url_args.items():
                if key is None:
                    continue
                placeholder = '{%s}' % key
                result = result.replace(placeholder, str(val))
        elif isinstance(url_args, (list, tuple)):
            for idx, val in enumerate(url_args):
