def parser_flags(parser):
    '''
    Given an argparse.ArgumentParser instance, return its argument flags in a space-separated
    string.
    '''
    try:
        if parser is None:
            return ''
        actions = getattr(parser, "_actions", [])
        if not actions:
            return ''
        flags = []
        seen = set()
        for action in actions:
            for flag in getattr(action, "option_strings", []):
                if flag not in seen:
                    seen.add(flag)
                    flags.append(flag)
        return ' '.join(flags)
    except Exception:
        return ''<|return|>

