        actions = getattr(parser, 'actions', None)
        if actions is None or not isinstance(actions, list):
            raise TypeError('Expected an argparse.ArgumentParser instance with "actions" attribute')
        flags = []
        for action in actions:
            option_strings = getattr(action, 'option_strings', None)
            if option_strings:
                flags.extend(option_strings)
