def vertex3tuple(vertices):
    """
    return 3 points for each vertex of the polygon. This will include the vertex and the 2 points on both sides of the vertex::

        polygon with vertices ABCD
        Will return
        DAB, ABC, BCD, CDA -> returns 3tuples
        #A    B    C    D  -> of vertices
    """
    try:
        verts = list(vertices)
    except TypeError as exc:
        raise TypeError("vertices must be an iterable of points") from exc

    n = len(verts)
    if n == 0:
        return []
    if n == 1:
        return [(verts[0], verts[0], verts[0])]
    if n == 2:
        return [
            (verts[0], verts[0], verts[1]),
            (verts[1], verts[0], verts[1]),
        ]

    return [(verts[i - 1], verts[i], verts[(i + 1) % n]) for i in range(n)]<|return|>

def int_to_string(number: int, alphabet: List[str], padding: Optional[int] = None) -> str:
    # Basic type checks
    if not isinstance(number, int):
        raise TypeError("number must be an integer")
    if not isinstance(alphabet, (list, tuple)):
        raise TypeError("alphabet must be a list or tuple of strings")
    if padding is not None:
        if not isinstance(padding, int):
            raise TypeError("padding must be an integer or None")
        if padding < 0:
            raise ValueError("padding must be non-negative")

    base = len(alphabet)
    if base < 2:
        raise ValueError("Alphabet must contain at least two symbols")

    sign = ''
    n = number
    if n < 0:
        sign = '-'
        n = -n

    # Convert number to base represented by alphabet
    if n == 0:
        digits = [alphabet[0]]
    else:
        digits = []
        while n > 0:
            digits.append(alphabet[n % base])
            n //= base
        digits.reverse()

    result = ''.join(digits)

    # Apply padding if requested
    if padding is not None and len(result) < padding:
        result = alphabet[0] * (padding - len(result)) + result

    return sign + result<|return|>

def int_to_string(number: int, alphabet: List[str], padding: Optional[int] = None) -> str:
    """
    Convert a number to a string, using the given alphabet.

    The output has the most significant digit first.
    """
    # Validate inputs
    if not isinstance(number, int):
        raise TypeError(f"number must be an integer, got {type(number).__name__}")
    if number < 0:
        raise ValueError("number must be non‑negative")
    if not isinstance(alphabet, (list, tuple)):
        raise TypeError(f"alphabet must be a list or tuple of strings, got {type(alphabet).__name__}")
    if len(alphabet) == 0:
        raise ValueError("alphabet must contain at least one symbol")
    if any(not isinstance(ch, str) for ch in alphabet):
        raise TypeError("all items in alphabet must be strings")
    if padding is not None:
        if not isinstance(padding, int):
            raise TypeError(f"padding must be an integer or None, got {type(padding).__name__}")
        if padding < 0:
            raise ValueError("padding must be non‑negative")

    base = len(alphabet)

    # Special handling for zero
    if number == 0:
        digits = [alphabet[0]]
    else:
        digits = []
        val = number
        while val:
            val, rem = divmod(val, base)
            digits.append(alphabet[rem])
        digits.reverse()

    result = ''.join(digits)

    # Apply padding if requested
    if padding is not None:
        if len(result) < padding:
            pad_len = padding - len(result)
            result = alphabet[0] * pad_len + result

    return result<|return|>

def int_to_string(number: int, alphabet: List[str], padding: Optional[int] = None) -> str:
    """
    Convert a number to a string, using the given alphabet.

    The output has the most significant digit first.
    """
    # Basic type validation
    if not isinstance(number, int):
        raise TypeError("number must be an int")
    if not isinstance(alphabet, list) or not all(isinstance(a, str) for a in alphabet):
        raise TypeError("alphabet must be a list of strings")
    if not alphabet:
        raise ValueError("alphabet cannot be empty")
    if len(alphabet) < 2 and number != 0:
        raise ValueError("alphabet with a single character cannot represent numbers > 0")
    if padding is not None:
        if not isinstance(padding, int):
            raise TypeError("padding must be an integer")
        if padding < 0:
            raise ValueError("padding must be non-negative")

    base = len(alphabet)
    n = abs(number)

    # Build digit list (least significant first)
    if n == 0:
        digits = [alphabet[0]]
    else:
        digits = []
        while n:
            n, rem = divmod(n, base)
            digits.append(alphabet[rem])

    # Most significant digit first
    digits.reverse()

    # Apply padding if requested
    if padding is not None and len(digits) < padding:
        digits = [alphabet[0]] * (padding - len(digits)) + digits

    result = ''.join(digits)

    # Add sign for negative numbers
    if number < 0:
        result = '-' + result

    return result<|return|>

