def _replace_register(flow_params, register_number, register_value):
    """
    Replace value from flows to given register number.

    The key named by ``register_value`` in any dictionary inside ``flow_params`` will be
    replaced with ``register_number`` while preserving its associated value. The
    replacement is performed recursively, handling nested dictionaries, lists, and
    tuples. If ``flow_params`` is not a container that can contain dictionaries
    the function returns it unchanged.

    :param flow_params: Dictionary (or nested container) containing the flows to
                        modify.
    :param register_number: The number (or key) that will replace ``register_value``.
    :param register_value: The key to be replaced.

    :return: The modified ``flow_params`` (the same object that was passed in).
    """
    # Bail early for non‑container types
    if not isinstance(flow_params, (dict, list, tuple)):
        return flow_params

    def _recurse(obj):
        if isinstance(obj, dict):
            # Work on a static list of keys because we may mutate the dict
            for key in list(obj.keys()):
                if key == register_value:
                    # Replace the key, preserving the value
                    try:
                        obj[register_number] = obj.pop(key)
                    except Exception:
                        # In case the key is unhashable or any other issue, skip
                        pass
                # Recursively process the value
                _recurse(obj[key])
        elif isinstance(obj, list):
            for item in obj:
                _recurse(item)
        elif isinstance(obj, tuple):
            for item in obj:
                _recurse(item)
        # Other types are left untouched

    try:
        _recurse(flow_params)
    except RecursionError:
        # In the unlikely event of a very deep structure, we silently abort
        pass

    return flow_params<|return|>

