    import shutil
    import tempfile
    from pathlib import Path

    # Resolve paths
    try:
        archive = Path(archive_path).expanduser().resolve()
    except Exception as e:
        raise ValueError(f"Invalid archive path '{archive_path}': {e}") from e

    if not archive.is_file():
        raise FileNotFoundError(f"Archive '{archive_path}' does not exist or is not a file.")

    tmp_dir = Path(tmp_path).expanduser().resolve()
    # Ensure base tmp directory exists
    try:
        tmp_dir.mkdir(parents=True, exist_ok=True)
    except OSError as e:
        raise OSError(f"Cannot create temporary directory '{tmp_dir}': {e}") from e

    # Determine target extraction directory
    if filename:
        dest_dir = tmp_dir / filename
        # avoid overwriting existing directory
        if dest_dir.exists():
            counter = 1
            while (tmp_dir / f"{filename}_{counter}").exists():
                counter += 1
            dest_dir = tmp_dir / f"{filename}_{counter}"
    else:
        # Use a unique temporary directory
        dest_dir = tempfile.mkdtemp(dir=tmp_dir)

    try:
        shutil.unpack_archive(str(archive), str(dest_dir))
    except shutil.ReadError as e:
        raise ValueError(f"Unsupported archive format or corrupted archive '{archive_path}': {e}") from e
    except Exception as e:
        raise RuntimeError(f"Failed to unpack archive '{archive_path}' into '{dest_dir}': {e}") from e

    return f"file://{Path(dest_dir).resolve()}"<|return|>

