    unit = unit.lower()
    # normalise unit forms
    unit_map = {
        'weeks': 'weeks',
        'week': 'weeks',
        'days': 'days',
        'day': 'days',
        'hours': 'hours',
        'hour': 'hours',
        'minutes': 'minutes',
        'minute': 'minutes',
        'secs': 'seconds',
        'sec': 'seconds',
        'seconds': 'seconds',
    }

    if unit not in unit_map:
        raise ValueError(f"unrecognized time unit in frequency: {unit!r}")

    kw = {unit_map[unit]: number}
    try:
        return datetime.timedelta(**kw)
    except Exception as exc:
        raise ValueError(f"error constructing timedelta for frequency {frequency!r}: {exc}") from exc<|return|>

def parse_frequency(frequency):
    '''
    Given a frequency string with a number and a unit of time, return a corresponding
    datetime.timedelta instance or None if the frequency is None or "always".

    For instance, given "3 weeks", return datetime.timedelta(weeks=3)

    Raise ValueError if the given frequency cannot be parsed.
    '''
    # Handle simple cases
    if frequency is None:
        return None
    if isinstance(frequency, str):
        freqs = frequency.strip().lower()
    else:
        raise ValueError("Frequency must be a string or None")
    if freqs == "always":
        return None
    if not freqs:
        raise ValueError("Empty frequency string")

    # Split into number and unit
    parts = freqs.split()
    if len(parts) != 2:
        raise ValueError(f"Cannot parse frequency: '{frequency}'")
    number_str, unit = parts
    try:
        number = int(number_str)
    except ValueError:
        # Try float if needed, but raise error if not whole number
        try:
            number = float(number_str)
        except ValueError:
            raise ValueError(f"Invalid number in frequency: '{number_str}'")

    # Normalize unit (remove trailing 's' for plural)
    unit = unit.rstrip('s')
    # Mapping units to timedelta arguments
    if unit == 'day':
        return datetime.timedelta(days=number)
    elif unit == 'week':
        return datetime.timedelta(weeks=number)
    elif unit == 'month':
        # Approximate a month as 30 days
        return datetime.timedelta(days=30 * number)
    elif unit == 'year':
        # Approximate a year as 365 days
        return datetime.timedelta(days=365 * number)
    else:
        raise ValueError(f"Unsupported time unit in frequency: '{unit}'")<|return|>

def is_local(host):
    """
    Checks if the host is the localhost

    :param host: The hostname or ip
    :return: True if the host is the localhost
    """
    try:
        host_str = str(host) if host is not None else ''
    except Exception:
        return False
    if not host_str:
        return False
    host_str = host_str.strip()
    if host_str.lower() == 'localhost':
        return True
    # Check if directly an IP and is loopback
    # IPv4
    try:
        packed_ipv4 = socket.inet_aton(host_str)
    except OSError:
        packed_ipv4 = None
    if packed_ipv4 and packed_ipv4[0] == 127:
        return True
    # IPv6
    try:
        packed_ipv6 = socket.inet_pton(socket.AF_INET6, host_str)
    except OSError:
        packed_ipv6 = None
    if packed_ipv6 and packed_ipv6 == b'\0' * 15 + b'\1':
        return True
    # Resolve hostname to IPs
    try:
        infos = socket.getaddrinfo(host_str, None, proto=socket.IPPROTO_TCP)
    except socket.gaierror:
        return False
    except Exception:
        return False
    for info in infos:
        sockaddr = info[4]
        addr = sockaddr[0]
        # Try IPv4 loopback
        try:
            packed = socket.inet_aton(addr)
            if packed[0] == 127:
                return True
        except OSError:
            pass
        # Try IPv6 loopback
        try:
            packed = socket.inet_pton(socket.AF_INET6, addr)
            if packed == b'\0' * 15 + b'\1':
                return True
        except OSError:
            pass
    return False<|return|>

def is_local(host):
