    :param host: The hostname or ip
    :return: True if the host is the localhost
    """
    # handle None or non-string inputs
    if not isinstance(host, str):
        return False

    host_str = host.strip()
    if not host_str:
        return False

    # Directly known loopback identifiers
    if host_str.lower() == 'localhost' or host_str == '127.0.0.1' or host_str == '::1':
        return True

    # Resolve the host to addresses and check for loopback
    try:
        addrinfo = socket.getaddrinfo(host_str, None)
    except socket.gaierror:
        return False

    for info in addrinfo:
        try:
            # info[4] is sockaddr; for IPv4 it's (addr, port), for IPv6 it's (addr, port, flowinfo, scopeid)
            sockaddr = info[4]
            ip_addr = sockaddr[0]
            if ip_addr.startswith('127.') or ip_addr == '::1':
                return True
        except Exception:
            continue

    return False<|return|>

def is_local(host):
    """
