    :param host: The hostname or ip
    :return: True if the host is the localhost
    """
    if host is None:
        return False
    host = host.strip()
    # Direct string checks
    if host in ("localhost", "127.0.0.1", "::1"):
        return True

    # Basic numeric IPv4 check
    try:
        parts = host.split('.')
        if len(parts) == 4:
            octets = [int(part) for part in parts]
            if octets[0] == 127:
                return True
    except Exception:
        pass

    # Basic numeric IPv6 check
    try:
        if host == "::1":
            return True
        if host.startswith("::ffff:127.") or host.startswith("::ffff:127."):
            return True
    except Exception:
        pass

    # Use getaddrinfo to resolve to numeric addresses
    try:
        addrinfo_list = socket.getaddrinfo(host, None)
        for family, _, _, _, sockaddr in addrinfo_list:
            if family == socket.AF_INET:
                ip = sockaddr[0]
                if ip.startswith("127."):
                    return True
            elif family == socket.AF_INET6:
                ip = sockaddr[0]
                if ip == "::1" or ip.startswith("::ffff:127."):
                    return True
    except socket.gaierror:
        return False
    except Exception:
        return False

    return False<|return|>

def is_local(host):
    """
    Checks if the host is the localhost

    :param host: The hostname or IP address as a string.
    :return: True if the host resolves to a loopback address (localhost), False otherwise.
    """
    if not isinstance(host, str):
        return False
    host = host.strip()
    if not host:
        return False

    # Direct string checks for common localhost representations
    if host in {"localhost", "127.0.0.1", "::1"}:
        return True

    # Attempt to resolve the host to all addresses and check for loopback
    try:
        for res in socket.getaddrinfo(host, None, family=socket.AF_UNSPEC, type=socket.SOCK_STREAM):
            ip = res[4][0]
            # IPv6 loopback
            if ip == "::1":
                return True
            # IPv4 loopback (127.0.0.0/8)
            if ip.startswith("127."):
                return True
    except Exception:
        # Any resolution error (e.g., unknown host) should not raise; treat as non-local
        return False

    return False<|return|>

def is_gitbash():
    """
    returns True if you run in a Windows gitbash

    :return: True if gitbash
    """
    try:
        # Git Bash only runs on Windows. Check for typical Git Bash environment variables.
        if os.name != 'nt':
            return False

        # $OSTYPE is set to 'msys', 'mingw', or similar in Git Bash.
        ostype = os.getenv('OSTYPE', '').lower()
        if ostype and ('msys' in ostype or 'mingw' in ostype):
            return True

        # $MSYSTEM is set only in MSYS2/Git Bash environments.
        if 'MSYSTEM' in os.environ:
            return True

        # As a fallback, check the executable path for MSYS prefixes.
        exe_path = os.path.realpath(os.path.abspath(sys.executable))
        if '/msys' in exe_path.lower() or '/mingw' in exe_path.lower():
            return True

        return False
    except Exception:
        return False<|return|>

