def write_configuration(config_filename, rendered_config, mode=0o600, overwrite=False):
    '''
    Given a target config filename and rendered config YAML, write it out to file.
    Create any containing directories as needed. But if the file already exists and
    overwrite is False, abort before writing anything.
    '''
    # Validate inputs
    if not isinstance(config_filename, (str, os.PathLike)):
        raise TypeError('config_filename must be a string or path-like object')
    if not isinstance(rendered_config, (str, bytes)):
        raise TypeError('rendered_config must be a string or bytes')
    if not isinstance(mode, int):
        raise TypeError('mode must be an integer')
    if not isinstance(overwrite, bool):
        raise TypeError('overwrite must be a boolean')

    # Resolve the target path and create directories if necessary
    path = os.fspath(config_filename)
    dir_name = os.path.dirname(path)
    if dir_name:
        os.makedirs(dir_name, exist_ok=True)

    # Check existence and decide flags
    exists = os.path.exists(path)
    if exists and not overwrite:
        raise FileExistsError(f'File "{path}" already exists and overwrite is False')
    flags = os.O_WRONLY | os.O_CREAT
    if exists and overwrite:
        flags |= os.O_TRUNC
    else:
        flags |= os.O_EXCL

    try:
        fd = os.open(path, flags, mode)
    except OSError as exc:
        raise

    try:
        with os.fdopen(fd, 'w', encoding='utf-8') as f:
            if isinstance(rendered_config, bytes):
                rendered_config = rendered_config.decode('utf-8')
            f.write(rendered_config)
    except Exception:
        # If anything goes wrong while writing, remove the incomplete file
        try:
            os.remove(path)
        except OSError:
            pass
        raise
    return None<|return|>

