def make_array(shape, dtype=np.dtype("float32")):
    """
    Function to create an array with shape and dtype.

    Parameters
    ----------
    shape : tuple
        shape of the array to create
    dtype : `numpy.dtype`
        data-type of the array to create

    Returns
    -------
    numpy.ndarray
        An array of zeros with the specified shape and dtype.
    """
    import numpy as np

    # Validate and normalize shape
    try:
        if isinstance(shape, int):
            shape = (shape,)
        elif isinstance(shape, (list, tuple)):
            shape = tuple(shape)
        else:
            raise TypeError
        if not all(isinstance(dim, int) and dim >= 0 for dim in shape):
            raise ValueError("All dimensions in shape must be non‑negative integers.")
    except Exception as exc:
        raise ValueError(f"Invalid shape argument {shape!r}: {exc}") from exc

    # Validate dtype
    try:
        dtype_resolved = np.dtype(dtype)
    except Exception as exc:
        raise ValueError(f"Invalid dtype argument {dtype!r}: {exc}") from exc

    # Create the array
    try:
        return np.zeros(shape, dtype=dtype_resolved)
    except Exception as exc:
        raise ValueError(f"Failed to create array with shape={shape} dtype={dtype_resolved}: {exc}") from exc<|return|>

