    """
    Gaussian centered around 0.2 with a sigma of 0.1.
    Accepts a numeric scalar or array-like input and returns the corresponding Gaussian values.
    Raises ValueError for invalid inputs.
    """
    center = 0.2
    sigma = 0.1
    if x is None:
        raise ValueError("Input cannot be None")
    try:
        x_arr = np.asarray(x, dtype=np.float64)
    except Exception as exc:
        raise ValueError("Input must be a number or array-like of numbers.") from exc
    if np.any(np.isnan(x_arr)):
