def gaussian(x):
    """Gaussian centered around 0.2 with a sigma of 0.1."""
    # Validate input
    if x is None:
        raise ValueError("Input cannot be None")
    try:
        x_arr = np.asarray(x, dtype=float)
    except Exception as exc:
        raise TypeError("Input must be convertible to a NumPy array") from exc

    # Compute Gaussian
    mu = 0.2
    sigma = 0.1
    norm = 1.0 / (sigma * np.sqrt(2 * np.pi))
    exp_term = np.exp(-0.5 * ((x_arr - mu) / sigma) ** 2)
    result = norm * exp_term

    # Preserve scalar output if given scalar input
    if np.isscalar(x):
        return float(result)
    return result
