def load_configurations(config_filenames, overrides=None, resolve_env=True):
    import logging
    import json
    import os
    import re

    def _resolve_env_in_value(value):
        """
        Recursively replace environment variable placeholders in strings.
        Supports ${VAR} or ${VAR:default}. Non-string values are returned unchanged.
        """
        if isinstance(value, dict):
            return {k: _resolve_env_in_value(v) for k, v in value.items()}
        if isinstance(value, list):
            return [_resolve_env_in_value(v) for v in value]
        if isinstance(value, str):
            pattern = r'\${([^}:]+)(?::([^}]+))?}'
            def repl(m):
                var = m.group(1)
                default = m.group(2)
                return os.getenv(var, default if default is not None else '')
            return re.sub(pattern, repl, value)
        return value

    configs = {}
    errors = []

    # Ensure we work with an iterable of filenames
    if isinstance(config_filenames, (str, bytes)):
        filenames = [config_filenames]
    else:
        filenames = list(config_filenames)

    for fname in filenames:
        try:
            with open(fname, 'r', encoding='utf-8') as f:
                data = f.read()
            try:
                parsed = json.loads(data)
            except json.JSONDecodeError as exc:
                record = logging.makeLogRecord({
                    'name': __name__,
                    'level': logging.ERROR,
                    'msg': f'JSON parse error in {fname}: {exc}',
                    'args': ()
                })
                errors.append(record)
                continue
        except FileNotFoundError:
            record = logging.makeLogRecord({
                'name': __name__,
                'level': logging.ERROR,
                'msg': f'File not found: {fname}',
                'args': ()
            })
            errors.append(record)
            continue
        except Exception as exc:
            record = logging.makeLogRecord({
                'name': __name__,
                'level': logging.ERROR,
                'msg': f'Error reading {fname}: {exc}',
                'args': ()
            })
            errors.append(record)
            continue

        # Apply overrides if provided
        if isinstance(overrides, dict):
            try:
                for k, v in overrides.items():
                    parsed[k] = v
            except Exception as exc:
                record = logging.makeLogRecord({
                    'name': __name__,
                    'level': logging.ERROR,
                    'msg': f'Error applying overrides to {fname}: {exc}',
                    'args': ()
                })
                errors.append(record)
                continue

        # Resolve environment variables if requested
        if resolve_env:
            try:
                parsed = _resolve_env_in_value(parsed)
            except Exception as exc:
                record = logging.makeLogRecord({
                    'name': __name__,
                    'level': logging.ERROR,
                    'msg': f'Error resolving env vars in {fname}: {exc}',
                    'args': ()
                })
                errors.append(record)
                continue

        configs[fname] = parsed

    return configs, errors<|return|>

