def load_configurations(config_filenames, overrides=None, resolve_env=True):
    '''
    Given a sequence of configuration filenames, load and validate each configuration file. Return
    the results as a tuple of: dict of configuration filename to corresponding parsed configuration,
    and sequence of logging.LogRecord instances containing any parse errors.
    '''
    import os
    import json
    import logging
    from json import JSONDecodeError

    # Ensure we have an iterable of filenames
    if isinstance(config_filenames, str):
        filenames = [config_filenames]
    else:
        try:
            filenames = list(config_filenames)
        except TypeError:
            raise TypeError("config_filenames must be a string or an iterable of strings")

    config_map = {}
    errors = []

    # Helper to recursively expand environment variables in configuration values
    def _expand_env(value):
        if isinstance(value, str):
            return os.path.expandvars(value)
        elif isinstance(value, dict):
            return {k: _expand_env(v) for k, v in value.items()}
        elif isinstance(value, list):
            return [_expand_env(v) for v in value]
        else:
            return value

    # Helper to create a LogRecord
    def _make_log_record(filename, message, exception=None):
        record = logging.LogRecord(
            name="config_loader",
            level=logging.ERROR,
            pathname=filename,
            lineno=0,
            msg=message,
            args=(),
            exc_info=exception
        )
        return record

    for filename in filenames:
        # Verify filename is a string
        if not isinstance(filename, str):
            error_msg = f"Configuration filename must be a string, got {type(filename).__name__}"
            errors.append(_make_log_record(filename, error_msg))
            continue

        # Attempt to open and parse the file
        try:
            with open(filename, 'r', encoding='utf-8') as f:
                try:
                    parsed = json.load(f)
                except JSONDecodeError as jde:
                    # JSON syntax error
                    errors.append(_make_log_record(filename, f"JSON decode error: {jde}", (jde, None, None)))
                    continue
        except FileNotFoundError as fnf:
            errors.append(_make_log_record(filename, f"Configuration file not found: {fnf}", (fnf, None, None)))
            continue
        except Exception as e:
            errors.append(_make_log_record(filename, f"Error reading configuration file: {e}", (e, None, None)))
            continue

        # Validate that the parsed config is a dictionary
        if not isinstance(parsed, dict):
            errors.append(_make_log_record(filename, f"Configuration must be a JSON object (dict), got {type(parsed).__name__}"))
            continue

        # Expand environment variables if requested
        if resolve_env:
            try:
                parsed = _expand_env(parsed)
            except Exception as e:
                errors.append(_make_log_record(filename, f"Error expanding environment variables: {e}", (e, None, None)))
                continue

        # Apply overrides if provided
        if overrides is not None:
            if not isinstance(overrides, dict):
                errors.append(_make_log_record(filename, f"Overrides must be a dict, got {type(overrides).__name__}"))
                # Continue without applying overrides
            else:
                try:
                    # Shallow merge: overrides replace top-level keys in the configuration
                    parsed.update(overrides)
                except Exception as e:
                    errors.append(_make_log_record(filename, f"Error applying overrides: {e}", (e, None, None)))
                    continue

        # Store the final configuration
        config_map[filename] = parsed

    return config_map, tuple(errors)<|return|>

