def _get_seq_with_type(seq, bufsize=None):
    """Return a (sequence, type) pair.
    Sequence is derived from *seq* (or is *seq*, if that is of a sequence type).
    """
    # Validate bufsize
    if bufsize is not None:
        if not isinstance(bufsize, int) or bufsize < 0:
            raise ValueError(f"bufsize must be a non‑negative integer or None, got {bufsize!r}")

    # Helper to determine if an object behaves like a sequence
    def _is_sequence(obj):
        return hasattr(obj, "__len__") and hasattr(obj, "__getitem__")

    # If seq is already a sequence, use it directly (optionally sliced)
    if _is_sequence(seq):
        seq_type = type(seq)
        if bufsize is not None and bufsize != 0:
            try:
                # Attempt slicing; if it fails, fall through to conversion path below
                seq = seq[:bufsize]
            except Exception:
                pass
        return seq, seq_type

    # If seq is None, raise an informative error
    if seq is None:
        raise TypeError("Cannot convert None to sequence")

    # seq is not a sequence, attempt to build a sequence from it
    try:
        if bufsize is not None:
            # Build a list iterating up to bufsize elements
            seq_list = []
            count = 0
            for item in seq:
                seq_list.append(item)
                count += 1
                if count >= bufsize:
                    break
            seq = seq_list
        else:
            seq = list(seq)
        return seq, type(seq)
    except TypeError as exc:
        # seq is not iterable
        raise TypeError(f"Object {seq!r} is not iterable and cannot be converted to a sequence") from exc
