        raise ValueError(f"Could not convert {seq!r} to sequence: {exc}") from exc<|return|>

def _get_seq_with_type(seq, bufsize=None):
    """Return a (sequence, type) pair.
    Sequence is derived from *seq*
    (or is *seq*, if that is of a sequence type).
    """
    # If seq is None, treat it as an empty sequence
    if seq is None:
        return ([], type(None))

    # Detect common sequence types that should be preserved
    if isinstance(seq, (list, tuple, range)):
        sequence = seq
    else:
        try:
            # Try to cast to a list; this will work for most iterables
            sequence = list(seq)
        except TypeError:
            # seq is not iterable; treat it as a single-element sequence
            sequence = [seq]

    # If bufsize was requested, truncate or extend the sequence accordingly
    if isinstance(bufsize, int) and bufsize >= 0:
        if len(sequence) > bufsize:
            sequence = sequence[:bufsize]
        elif len(sequence) < bufsize:
            # Extend with the last element or None if sequence empty
