        # Extract key attributes flexibly (allow dicts or objects)
        if isinstance(request, dict):
            path = request.get("path") or request.get("url")
            method = request.get("method")
            headers = request.get("headers", {})
        else:
            path = getattr(request, "path", None) or getattr(request, "url", None)
            method = getattr(request, "method", None)
            headers = getattr(request, "headers", {})

        # Ensure headers is a dictionary
        if not isinstance(headers, dict):
            headers = {}

        # Verify the path is a string
        if not isinstance(path, str):
