        # Some servers mark Matrix requests with a dedicated header
        if headers.get("X-Matrix-Request", "").lower() in ("true", "1", "yes"):
            return True

        # Content‑type can give a hint, especially for POST/GET login calls
        content_type = (
            headers.get("Content-Type") or headers.get("content-type") or ""
        ).lower()
        if content_type and "application/json" in content_type:
            # If the request uses POST or GET but the path doesn't start with a slash
            # (common in some Matrix clients), we lean toward it being Matrix.
            if method in ("POST", "GET") and not path.startswith("/"):
