    if isinstance(dt, datetime.datetime):
        # Normalize to UTC
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        else:
            dt = dt.astimezone(datetime.timezone.utc)
        # Return ISO 8601 string with milliseconds and trailing 'Z'
        return dt.strftime("%Y-%m-%dT%H:%M:%S.%f")[:-3] + "Z"
    # Handle date objects (without time)
    if isinstance(dt, datetime.date) and not isinstance(dt, datetime.datetime):
        return dt.strftime("%Y-%m-%d")
    # Attempt to parse a string representation
    if isinstance(dt, str):
        try:
            parsed = datetime.datetime.fromisoformat(dt)
            return format_dt(parsed)
        except Exception:
            raise ValueError(f"Unrecognized date/time format: {dt!r}")
    raise ValueError(f"Unsupported type for date/time formatting: {type(dt).__name__}")<|return|>

