def parse_diaspora_webfinger(document: str) -> Dict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    For the JSON format the function expects a top level structure similar to:
    {
      "Subject": "acct:user@example.com",
      "Links": [
        {"rel": "http://webfinger.net/rel/profile-page",
         "type": "text/html",
         "href": "https://example.com/user"},
        {"rel": "http://webfinger.diaspora.software/rel/storage-service",
         "type": "application/xml",
         "href": "https://example.com/storage"}
      ]
    }

    For the XRD format the XML will look like:
    <xrd xmlns="http://docs.oasis-open.org/ns/xri/xrd-1.0">
        <Subject>acct:user@example.com</Subject>
        <Link rel="http://webfinger.net/rel/profile-page"
              type="text/html"
              href="https://example.com/user"/>
        ...
    </xrd>

    The returned dictionary will have the following keys:
        - "subject": subject string (or None if not found)
        - "links": a list of dictionaries, each with at least:
            * "rel" (str)
            * "href" (str)
            * "type" (str, optional)

    If the document cannot be parsed as either JSON or XRD, a ValueError is raised.
    """

    # Basic validation of input
    if not isinstance(document, str) or not document.strip():
        return {}

    import json
    import xml.etree.ElementTree as ET

    def _build_links_from_items(items):
        links = []
        for it in items:
            # Each item could be a dict (JSON) or xml.Element (XRD)
            if isinstance(it, dict):
                rel = it.get("rel") or it.get("rel")
                href = it.get("href")
                typ = it.get("type")
                if rel and href:
                    link = {"rel": rel, "href": href}
                    if typ:
                        link["type"] = typ
                    links.append(link)
            elif isinstance(it, ET.Element):
                rel = it.attrib.get("rel")
                href = it.attrib.get("href")
                typ = it.attrib.get("type")
                if rel and href:
                    link = {"rel": rel, "href": href}
                    if typ:
                        link["type"] = typ
                    links.append(link)
        return links

    # Attempt JSON parsing first
    try:
        data = json.loads(document.strip())
        if isinstance(data, dict) and ("Subject" in data or "subject" in data):
            subject = data.get("Subject") or data.get("subject")
            # Links could be under "Links" or "links"
            links_items = data.get("Links") or data.get("links") or []
            links = _build_links_from_items(links_items)
            return {"subject": subject, "links": links}
    except Exception:
        # Not JSON or JSON invalid; fall back to XRD
        pass

    # Attempt XML parsing (XRD)
    try:
        # Parse XML with namespaces handled
        root = ET.fromstring(document.strip())
        # The default namespace might be enclosed; strip it for easy access
        ns = {}
        for ns_prefix, ns_uri in root.attrib.items():
            if ns_prefix.startswith("xmlns"):
                ns[ns_prefix[6:]] = ns_uri
        # Determine namespace map; often default namespace is at index 0
        if root.tag.startswith("{"):
            ns_uri = root.tag.split("}")[0][1:]
            ns_prefix = "xrd"
            ns[ns_prefix] = ns_uri
        # Helper to find elements with namespace
        def find(tag, default_ns=None):
            if default_ns:
                return root.find(f"{{{default_ns}}}{tag}")
            return root.find(tag)
        # Search for Subject
        subject_el = find("Subject", root.tag.split("}")[0][1:] if "}" in root.tag else None)
        subject = subject_el.text.strip() if subject_el is not None and subject_el.text else None
        # Find all Link elements
        links_el = root.findall(f"{{{root.tag.split('}')[0][1:]}}}Link") if "}" in root.tag else root.findall("Link")
        links_items = links_el

