        data = json.loads(document)
        if not isinstance(data, dict):
            raise ValueError("JSON root not an object")
        result: Dict = {}
        if 'subject' in data:
            result['subject'] = data['subject']
        else:
            result['subject'] = ''
        if 'aliases' in data and isinstance(data['aliases'], list):
            result['aliases'] = list(data['aliases'])
        else:
            result['aliases'] = []
        # Parse links
        links = []
        for l in data.get('links', []):
            if isinstance(l, dict):
                link = {}
                for key in ('rel', 'type', 'href'):
                    if key in l:
                        link[key] = l[key]
                if link:
                    links.append(link)
        result['links'] = links
        return result
    except (JSONDecodeError, ValueError):
        pass

    # Fallback to XRD (XML) parsing
    try:
        root = ET.fromstring(document)
        _clean_namespace(root)

        subject = ""
        aliases = []
        links = []

        # Subject
        subject_elem = root.find('Subject')
        if subject_elem is not None and subject_elem.text:
            subject = subject_elem.text

        # Aliases
        for alias_elem in root.findall('Alias'):
            if alias_elem.text:
                aliases.append(alias_elem.text)

        # Links
        for link_elem in root.findall('Link'):
            link = {}
            rel = link_elem.get('rel')
            r_type = link_elem.get('type')
            href = link_elem.get('href')
            if rel:
                link['rel'] = rel
            if r_type:
                link['type'] = r_type
            if href:
                link['href'] = href
            if link:
                links.append(link)

        return {
            'subject': subject,
            'aliases': aliases,
            'links': links
        }
    except ET.ParseError:
        pass

    # If all parsing fails, return empty dict
    return {}<|return|>

def parse_diaspora_webfinger(document: str) -> Dict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    import json
    import xml.etree.ElementTree as ET

    def _parse_json(doc: str) -> dict:
        try:
            data = json.loads(doc)
        except ValueError as exc:
            raise ValueError("Invalid JSON") from exc

        result = {}
        if isinstance(data, dict):
            result["subject"] = data.get("subject", "")
            result["aliases"] = data.get("aliases", [])
            links = data.get("links", [])
            if isinstance(links, list):
                result["links"] = links
            else:
                result["links"] = []
        else:
            raise ValueError("JSON root must be an object")
        return result

    def _parse_xrd(doc: str) -> dict:
        ns = {"xrd": "http://docs.oasis-open.org/ns/xri/xrd-1.0"}
        try:
            root = ET.fromstring(doc)
        except ET.ParseError as exc:
            raise ValueError("Invalid XRD XML") from exc

        subject_el = root.find("xrd:subject", ns)
        subject = subject_el.text if subject_el is not None else ""

        aliases = []
        for alias_el in root.findall("xrd:alias", ns):
            if alias_el.text:
                aliases.append(alias_el.text)

        links = []
        for link_el in root.findall("xrd:link", ns):
            link = {}
            for attr in ("rel", "type", "href"):
                val = link_el.attrib.get(attr)
                if val is not None:
                    link[attr] = val
            if link:
                links.append(link)

        return {"subject": subject, "aliases": aliases, "links": links}

    # First attempt JSON
    try:
        return _parse_json(document)
    except ValueError:
        # Not JSON; try XRD
        return _parse_xrd(document)<|return|>

def parse_diaspora_webfinger(document: str) -> Dict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    import json
    import xml.etree.ElementTree as ET

    def _strip_namespace(tag: str) -> str:
        return tag.split("}")[-1] if "}" in tag else tag

    # Try JSON first
    try:
        parsed = json.loads(document)
        if isinstance(parsed, dict):
            # Ensure the keys we care about are present
            subject = parsed.get("subject")
            aliases = parsed.get("aliases", [])
            links = parsed.get("links", [])
            return {
                "subject": subject,
                "aliases": aliases,
                "links": links,
            }
    except Exception:
        pass

    # Fallback to XRD (XML)
    try:
        root = ET.fromstring(document)
        subject = None
        aliases = []
        links = []

        for child in root:
            tag = _strip_namespace(child.tag)
            if tag == "Subject":
                subject = child.text.strip() if child.text else None
            elif tag == "Alias":
                if child.text:
                    aliases.append(child.text.strip())
            elif tag == "Link":
                # Link elements are typically attributes
                link_attrs = {k: v for k, v in child.attrib.items()}
                links.append(link_attrs)

        if subject is None:
            # If no subject found, try deeper search
            for elem in root.iter():
                if _strip_namespace(elem.tag) == "Subject":
                    subject = elem.text.strip() if elem.text else None
                    break

        result = {
            "subject": subject,
            "aliases": aliases,
            "links": links,
        }
        # Only return a non-empty result
        if any([subject, aliases, links]):
            return result
    except Exception:
        pass

    # If parsing failed, raise a ValueError
    raise ValueError("Unable to parse Diaspora webfinger document.")<|return|>

def try_retrieve_webfinger_document(handle: str) -> Optional[str]:
    """
    Try to retrieve an RFC7033 webfinger document. Does not raise if it fails.
    """
    if not handle or '@' not in handle:
        return None
    try:
        from urllib import request as _request, parse as _parse, error as _error
    except Exception:
        return None

    domain = handle.split('@', 1)[1]
    # Ensure the resource string is properly quoted
    try:
        resource = _parse.quote(f"acct:{handle}", safe='')
    except Exception:
        return None

    url = f"https://{domain}/.well-known/webfinger?resource={resource}"
    try:
        with _request.urlopen(url, timeout=5) as resp:
            if resp.status != 200:
                return None
            body_bytes = resp.read()
            try:
                return body_bytes.decode('utf-8')
            except Exception:
                return None
    except (_error.HTTPError, _error.URLError, Exception):
        return None
<|return|>

def try_retrieve_webfinger_document(handle: str) -> Optional[str]:
    """
    Try to retrieve an RFC7033 webfinger document. Does not raise if it fails.
    """
    try:
        if not isinstance(handle, str) or '@' not in handle:
            return None

        local, domain = handle.split('@', 1)
        schemes = ['https', 'http']
        for scheme in schemes:
            try:
                url = f"{scheme}://{domain}/.well-known/webfinger?resource=acct:{handle}"
                request = __import__('urllib.request').Request(
                    url,
                    headers={"User-Agent": "py-webfinger-client"}
                )
                with __import__('urllib.request').urlopen(request, timeout=5) as resp:
                    if getattr(resp, "getcode", lambda: None)() == 200:
                        data = resp.read()
                        # Try to decode using utf-8, fallback to iso-8859-1 if needed
                        try:
                            return data.decode('utf-8')
                        except UnicodeDecodeError:
                            return data.decode('iso-8859-1')
            except Exception:
                # Try next scheme
                continue
        return None
    except Exception:
        return None<|return|>

def retrieve_and_parse_diaspora_webfinger(handle):
    """
    Retrieve a and parse a remote Diaspora webfinger document.

    :arg handle: Remote handle to retrieve
    :returns: dict
    """
    import json
    import urllib.request
    import urllib.parse
    from urllib.error import URLError, HTTPError

    # Basic validation of the handle
    if not isinstance(handle, str) or '@' not in handle:
        return {}

    user_part, domain = handle.split('@', 1)
    if not user_part or not domain:
        return {}

    # The domain should have at least one dot to be a valid FQDN
    if '.' not in domain:
        return {}

    # Prepare the webfinger URL
    resource = urllib.parse.quote_plus(f"acct:{handle}")
    webfinger_url = f"https://{domain}/.well-known/webfinger?resource={resource}"

    try:
        req = urllib.request.Request(
            webfinger_url,
            headers={"User-Agent": "DiasporaWebfingerRetriever/1.0"}
        )
        with urllib.request.urlopen(req, timeout=10) as response:
            data_bytes = response.read()
            try:
                data_str = data_bytes.decode('utf-8')
            except UnicodeDecodeError:
                # try decoding with latin1 fallback
                data_str = data_bytes.decode('latin1')
            try:
                json_obj = json.loads(data_str)
            except json.JSONDecodeError:
                # Not JSON, attempt to parse as XML or return empty
                return {}
            return json_obj
    except (URLError, HTTPError):
        # network errors or HTTP errors
        return {}
    except Exception:
        # catch-all for unforeseen errors
        return {}
