def retrieve_and_parse_diaspora_webfinger(handle):
    """
    Retrieve a and parse a remote Diaspora webfinger document.

    :arg handle: Remote handle to retrieve
    :returns: dict
    """
    if not isinstance(handle, str) or '@' not in handle:
        raise ValueError("handle must be a string of the form 'user@domain'")
    try:
        import urllib.request
        import urllib.error
        import json

        domain = handle.split('@', 1)[1]
        url = f"https://{domain}/.well-known/webfinger?resource=acct:{handle}"
        # Some diaspora instances may not support SSL; try http if https fails
        try:
            with urllib.request.urlopen(url, timeout=10) as resp:
                status = resp.getcode()
                if status >= 400:
                    raise urllib.error.HTTPError(url, status, resp.reason, resp.headers, None)
                content = resp.read()
                enc = resp.headers.get_content_charset('utf-8')
        except urllib.error.URLError:
            # retry with http
            url = f"http://{domain}/.well-known/webfinger?resource=acct:{handle}"
            with urllib.request.urlopen(url, timeout=10) as resp:
                status = resp.getcode()
                if status >= 400:
                    raise urllib.error.HTTPError(url, status, resp.reason, resp.headers, None)
                content = resp.read()
                enc = resp.headers.get_content_charset('utf-8')
        if isinstance(content, bytes):
            data = content.decode(enc, errors='ignore')
        else:
            data = content

        # Try to parse as JSON – Diaspora uses JSON webfinger
        try:
            result = json.loads(data)
            if not isinstance(result, dict):
                raise ValueError("Parsed webfinger JSON is not a dict")
            return result
        except json.JSONDecodeError:
            # Could not parse as JSON – return empty dict or raise
            raise ValueError("Could not parse webfinger response as JSON")
    except urllib.error.HTTPError as he:
        raise RuntimeError(f"HTTP error fetching webfinger for {handle}: {he}") from he
    except urllib.error.URLError as ue:
        raise RuntimeError(f"URL error fetching webfinger for {handle}: {ue}") from ue
