def retrieve_diaspora_host_meta(host):
    """
    Retrieve a remote Diaspora host-meta document.

    :arg host: Host to retrieve from
    :returns: ``XRD`` instance
    :raises ValueError: if host is empty or invalid
    :raises RuntimeError: if network or parsing errors occur
    """
    # Validate input
    if not host or not isinstance(host, str):
        raise ValueError("host must be a non-empty string")

    # Ensure host uses a scheme
    if not host.lower().startswith(("http://", "https://")):
        host_str = f"https://{host}"
    else:
        host_str = host

    # Normalize host string: remove trailing slash
    host_str = host_str.rstrip("/")

    # Construct the host-meta URL
    host_meta_url = f"{host_str}/.well-known/diaspora/host-meta"

    try:
        # Use urllib to fetch the document
        from urllib import request, error as urllib_error

        req = request.Request(host_meta_url, headers={"Accept": "application/xrd+xml"})
        with request.urlopen(req, timeout=10) as resp:
            content = resp.read()
    except urllib_error.HTTPError as e:
        raise RuntimeError(f"HTTP error retrieving host meta: {e.code} {e.reason}") from e
    except urllib_error.URLError as e:
        raise RuntimeError(f"URL error retrieving host meta: {e.reason}") from e
    except Exception as e:
        raise RuntimeError(f"Unexpected error retrieving host meta: {e}") from e

    # Parse the XML
    try:
        from xml.etree import ElementTree as ET
        root = ET.fromstring(content)
    except ET.ParseError as e:
        raise RuntimeError(f"Error parsing XRD XML: {e}") from e
    except Exception as e:
        raise RuntimeError(f"Unexpected error parsing XRD XML: {e}") from e

    # Attempt to import the XRD class; fallback to a simple wrapper if unavailable
    try:
        from xrd import XRD
    except ImportError:
        class XRD:
            def __init__(self, root_element):
                self.root = root_element

    return XRD(root)<|return|>

