def retrieve_diaspora_host_meta(host):
    """
    Retrieve a remote Diaspora host‑meta document.

    :arg host: Host to retrieve from
    :returns: ``XRD`` instance
    """
    import urllib.request
    import urllib.error
    import ssl
    import xml.etree.ElementTree as ET

    if not host or not isinstance(host, str):
        raise ValueError("host must be a non‑empty string")

    # Build the host‑meta URL using https first, fall back to http
    urls = [
        f"https://{host}/.well-known/host-meta?format=xrd",
        f"http://{host}/.well-known/host-meta?format=xrd",
    ]

    # Helper to fetch the document
    def _fetch(url):
        try:
            context = ssl.create_default_context()
            # In case the host uses a self‑signed certificate, we do not
            # want to silently ignore errors – let the caller see the
            # exception for proper debugging.
            with urllib.request.urlopen(url, timeout=5, context=context) as resp:
                if resp.getcode() != 200:
                    raise urllib.error.HTTPError(url, resp.getcode(), resp.reason, resp.headers, None)
                return resp.read()
        except urllib.error.URLError as e:
            raise ConnectionError(f"Could not retrieve host‑meta from {url}: {e}") from e

    # Try each URL until succeed
    raw_xml = None
    for url in urls:
        try:
            raw_xml = _fetch(url)
            break
        except Exception:
            continue
    if raw_xml is None:
        raise FileNotFoundError(f"Host‑meta not found for {host}")

    # Parse XML
    try:
        root = ET.fromstring(raw_xml)
    except ET.ParseError as e:
        raise ValueError(f"Invalid host‑meta XML for {host}: {e}") from e

    # Try to convert to an XRD instance if the library is available
    try:
        from diaspora.utils.xrd import XRD  # type: ignore
        return XRD.from_xml(root) if hasattr(XRD, "from_xml") else XRD(root)
    except Exception:
        # Fallback: return the parsed ElementTree Element
        return root
<|return|>

def send_document(url, data, timeout=10, method="post", *args, **kwargs):
    """Helper method to send a document via POST.

    Additional ``*args`` and ``**kwargs`` will be passed on to ``requests.post``.

    :arg url: Full url to send to, including protocol
    :arg data: Dictionary (will be form-encoded), bytes, or file-like object to send in the body
    :arg timeout: Seconds to wait for response (defaults to 10)
    :arg method: Method to use, defaults to post
    :returns: Tuple of status code (int or None) and error (exception class instance or None)
    """
    # Validate URL
    if not isinstance(url, str) or not url:
        raise ValueError("url must be a non-empty string")
    # Validate method
    method = method.lower() if isinstance(method, str) else method
    # Ensure timeout is numeric
    try:
        timeout_val = float(timeout)
    except (TypeError, ValueError):
        raise ValueError("timeout must be a number")
    try:
        if method == "post":
            response = requests.post(url, data=data, timeout=timeout_val, *args, **kwargs)
        else:
            # Use generic request method for flexibility
            response = requests.request(method, url, data=data, timeout=timeout_val, *args, **kwargs)
        return (response.status_code if response is not None else None, None)
    except Exception as e:
        return (None, e)<|return|>

def list_of_file_names(settings_dirs, spec_option):
    """
    Create a new IniType complex type

    Parameters
    ----------
    settings_dirs : Union[str, Iterable[str]]
        One or multiple directory paths to search for files.
    spec_option : dict or None
        Optional specification that may contain filtering keys:
        - `extension`: a file extension string (e.g. ".ini") to match.
        - `prefix`: a filename prefix to match.
        - `recursive`: bool, if True search subdirectories recursively.
          Defaults to False.
        If None, all files are returned.

    Returns
    -------
    List[str]
        A list of full file paths that satisfy the specified criteria.
        The list is sorted lexicographically.

    Notes
    -----
    Any directory that does not exist or cannot be accessed is silently
    skipped; a warning is printed to stderr. Invalid types or values
    result in a ValueError.
    """
    # Importing inside the function to keep the module self‑contained
    import os

    # Validate and normalise settings_dirs
    if isinstance(settings_dirs, (str, bytes)):
        dir_list = [settings_dirs]
    else:
        try:
            dir_list = list(settings_dirs)
        except TypeError:
            raise ValueError("settings_dirs must be a string or an iterable of strings")

    # Normalise spec_option
    if spec_option is None:
        spec_option = {}
    elif not isinstance(spec_option, dict):
        raise ValueError("spec_option must be a dict or None")

    ext = spec_option.get("extension")
    prefix = spec_option.get("prefix")
    recursive = spec_option.get("recursive", False)

    # If the extension string does not start with a dot, prepend one.
    if ext and not ext.startswith("."):
        ext = "." + ext

    found_files = []

    for d in dir_list:
        try:
            if not os.path.isdir(d):
                # Skip non-existent or non-directory entries
                continue
        except Exception:
            continue

        if recursive:
            for root, _, files in os.walk(d, followlinks=False):
                for fname in files:
                    if ext and not fname.endswith(ext):
                        continue
                    if prefix and not fname.startswith(prefix):
                        continue
                    full_path = os.path.join(root, fname)
                    found_files.append(full_path)
        else:
            try:
                for fname in os.listdir(d):
                    full_path = os.path.join(d, fname)
                    if not os.path.isfile(full_path):
                        continue
                    if ext and not fname.endswith(ext):
                        continue
                    if prefix and not fname.startswith(prefix):
                        continue
                    found_files.append(full_path)
            except (OSError, PermissionError):
                continue

    return sorted(found_files)<|return|>

def list_of_file_names(settings_dirs, spec_option):
    """
    Create a new IniType complex type

    Returns a list of file paths that exist in the given directories and
    match the optional spec_option pattern.  If spec_option is None or an
    empty string, all files are returned.  The function is tolerant of
    non-existent directories and will simply skip them.  Leading and
    trailing whitespace in spec_option is ignored.  The returned list is
    sorted to provide a deterministic order.

    Parameters
    ----------
    settings_dirs : str | Iterable[str]
        One or more directory paths to search for files.
    spec_option : str | Iterable[str] | None
        Optional file name pattern(s).  May contain glob wildcards
        (e.g. '*.ini').  If iterable, each element is considered a
        separate pattern.  If None or empty, no filtering is applied.

    Returns
    -------
    list[str]
