def get_spec_defaults(self):
        """Resolve arguments' values from spec and other sources.

        The method returns a dictionary that contains the resolved
        values for each argument defined in ``self.spec``.  Default
        values are extracted from the spec; if ``self.args`` is
        present, its values override the defaults.  The implementation
        is defensive and works with several common spec shapes:
        - a mapping of argument names to a definition dict that may
          contain a ``"default"`` key,
        - a list of argument names (defaults are ``None``),
        - a list of definition dicts that optionally include a ``"name"``
          and ``"default"`` key.
        It will silently ignore unexpected shapes and return an empty
        dictionary if no spec is available.  Any errors encountered
        while reading the spec or args are swallowed and an empty
        dict is returned instead of raising an exception.
        """
        try:
            spec = getattr(self, "spec", None)
            if not spec:
                return {}

            defaults = {}
            # Handle spec as a mapping (dict)
            if isinstance(spec, dict):
                for arg_name, arg_def in spec.items():
                    if isinstance(arg_def, dict):
                        defaults[arg_name] = arg_def.get("default")
                    else:
                        # When the dictionary value is directly the default
                        defaults[arg_name] = arg_def
            # Handle spec as a list
            elif isinstance(spec, list):
                for item in spec:
                    if isinstance(item, dict):
                        name = item.get("name")
                        if name is not None:
                            defaults[name] = item.get("default")
                    elif isinstance(item, str):
                        defaults[item] = None

            # Merge with any user-supplied arguments
            args = getattr(self, "args", {})
            if isinstance(args, dict):
                # User-supplied values take precedence
                defaults.update(args)

            return defaults
        except Exception:
            # On any unexpected error, return an empty mapping
            return {}<|return|>

