def get_parser_option_specs(self, command_name):
    """Gets all the options for the specified command

    :param command_name: the command name (main, virsh, ospd, etc...)
    :return: the list of all command options
    """
    if not isinstance(command_name, str):
        raise TypeError("command_name must be a string")
    command_name = command_name.strip()
    if not command_name:
        raise ValueError("command_name cannot be empty")

    # The parser option specs are stored in the instance under the private attribute
    # `_option_specs` as a mapping from command names to a list of option objects.
    # If the attribute does not exist, we treat it as no commands defined.
    option_specs_map = getattr(self, "_option_specs", {})
    if not isinstance(option_specs_map, dict):
        # Unexpected structure – raise a clear error for easier debugging.
        raise RuntimeError(f"Internal `_option_specs` attribute has unexpected type {type(option_specs_map)!r}")

    try:
        specs = option_specs_map[command_name]
    except KeyError:
        raise KeyError(f"No option specifications found for command '{command_name}'")

    # Ensure we return a copy so callers cannot modify the internal state
    if isinstance(specs, list):
        return list(specs)
    # If the stored value is not a list, coerce it into a list
    return [specs] if specs is not None else []<|return|>

def get_parser_option_specs(self, command_name):
        """Gets all the options for the specified command

        :param command_name: the command name (main, virsh, ospd, etc...)
        :return: the list of all command options
        """
        # Validate input
        if not isinstance(command_name, str):
            raise ValueError("command_name must be a string")
        # Find the subparser for the given command name
        try:
            # Some ArgumentParser instances expose the subparsers through a private
            # attribute named "_subparsers".  Others may expose it via "subparsers".
            subparsers = getattr(self.parser, "_subparsers", None)
            if subparsers is None:
                subparsers = getattr(self.parser, "subparsers", None)
            if subparsers is None:
                raise AttributeError("Parser does not contain subparsers")
            # _SubParsersAction usually owns a 'choices' dictionary that maps command
            # names to their respective ArgumentParser objects.
            parser_mapping = getattr(subparsers, "choices", {})
            if command_name not in parser_mapping:
                raise KeyError(f"Command '{command_name}' not found in parser")
            command_parser = parser_mapping[command_name]
        except AttributeError:
            # No subparsers available – cannot provide options
            raise AttributeError(
                f"Parser object of type {type(self.parser).__name__} does not support subparsers"
            ) from None
        except KeyError as exc:
            # Command does not exist; raise a more descriptive exception
            raise KeyError(f"Command '{command_name}' not found in parser") from exc

        # Extract all option strings from the command's ArgumentParser
        options = set()
        try:
            for action in getattr(command_parser, "_actions", []):
                # Each action may have one or more option strings (e.g. ["-f", "--foo"])
                if hasattr(action, "option_strings"):
                    options.update(action.option_strings)
        except Exception:
            # If anything unexpected occurs during extraction, swallow and return empty set
            options = set()

        # Return a sorted list for deterministic ordering
        return sorted(options)<|return|>

def get_option_spec(self, command_name, argument_name):
