def get_option_spec(self, command_name, argument_name):
    """
    Gets the specification for the specified option name.
    Returns the spec dictionary or object for the given command and option.
    Raises KeyError if the command or option is not found.
    Raises AttributeError if the required internal structures are missing.
    """
    # Basic validation of inputs
    if command_name is None:
        raise ValueError("command_name must not be None")
    if argument_name is None:
        raise ValueError("argument_name must not be None")

    # Determine where the command specs are stored.
    # We look for common attribute names that might hold the commands mapping.
    cmd_attrs = ('commands', 'command_specs', 'specs', 'commands_map')
    commands_obj = None
    for attr in cmd_attrs:
        if hasattr(self, attr):
            commands_obj = getattr(self, attr)
            break
    if commands_obj is None:
        raise AttributeError("No attribute holding command specifications was found on the instance.")
    if not isinstance(commands_obj, dict):
        raise TypeError(f"Attribute holding command specifications should be a dict, got {type(commands_obj)!r}")

    # Retrieve the command specification
    try:
        command_spec = commands_obj[command_name]
    except KeyError:
        raise KeyError(f"Command '{command_name}' not found in the command specifications.") from None

    # Find the options dictionary inside the command spec.
    # Some frameworks use different keys for options; we check a few common ones.
    option_attrs = ('options', 'arguments', 'args', 'options_spec')
    options_obj = None
    if isinstance(command_spec, dict):
        for opt_attr in option_attrs:
            if opt_attr in command_spec:
                options_obj = command_spec[opt_attr]
                break
    if options_obj is None:
        raise KeyError(f"No options found for command '{command_name}'.")
    if not isinstance(options_obj, dict):
        raise TypeError(f"Expected options to be a dict for command '{command_name}', got {type(options_obj)!r}")

    # Retrieve the specific option specification
    try:
        spec = options_obj[argument_name]
    except KeyError:
        raise KeyError(f"Option '{argument_name}' not found for command '{command_name}'.") from None

    return spec
