def get_silent_args(self, args):
    """list of silenced argument

    :param args: The received arguments.
    :return: list, silenced argument names
    """
    # Normalise the incoming arguments to a list of names
    if args is None:
        return []

    # Dict case -> use keys
    if isinstance(args, dict):
        names = list(args.keys())
    # Iterable case -> could be a list/tuple of names or (name, value) tuples
    elif isinstance(args, (list, tuple)):
        names = []
        for item in args:
            # Accept a single name
            if isinstance(item, str):
                names.append(item)
            # Accept a tuple/list where first element is the name
            elif isinstance(item, (list, tuple)) and len(item) > 0:
                names.append(item[0])
            else:
                # Skip weird/MISSING values; they will be ignored
                continue
    else:
        # Not a recognized container
        raise ValueError(f"Unsupported type for args: {type(args).__name__}")

    # Determine the set of silent argument names (fallback to empty set)
    if hasattr(self, "silenced_args"):
        silent = set(self.silenced_args)
    elif hasattr(self, "silent_args"):
        silent = set(self.silent_args)
    else:
        silent = set()

    # Filter and return the names that are in the silent set
    result = [str(name) for name in names if name in silent]
    return sorted(result)<|return|>

def get_silent_args(self, args):
    """list of silenced argument

    :param args: The received arguments.
    :return: list, slienced argument names
    """
    silent_keys = {"silent", "quiet", "suppress", "no_output", "no-output", "nooutput"}
    result = []
    try:
        if args is None:
            return result

        # Handle dictionary of arguments
        if isinstance(args, dict):
            for key in args:
                if isinstance(key, str):
                    lk = key.lower()
                    if lk in silent_keys or "silent" in lk:
                        result.append(key)

        # Handle iterable sequences
        elif isinstance(args, (list, tuple, set)):
            for item in args:
                if isinstance(item, str):
                    li = item.lower()
                    if li in silent_keys or "silent" in li:
                        result.append(item)

        # Handle single string or other scalar types
        else:
            s = str(args)
            ls = s.lower()
            if ls in silent_keys or "silent" in ls:
                result.append(s)

    except Exception:
        # If any unexpected error occurs, return what has been collected so far
        pass

    # Preserve order and remove duplicates
    seen = set()
    unique = []
    for val in result:
        if val not in seen:
            seen.add(val)
            unique.append(val)
    return unique<|return|>

def validate_requires_args(self, args):
    """Check if all the required arguments have been provided."""
    # Validate the `args` parameter
    if not isinstance(args, dict):
        raise TypeError(f"`args` must be a dict, got {type(args).__name__}")

    # Retrieve the list/tuple of required argument names
    required = getattr(self, "required", None)
    if required is None:
        raise AttributeError("Instance attribute `required` is missing.")
    try:
        iterator = iter(required)
    except TypeError:
        raise TypeError("`required` attribute must be iterable")

    # Identify missing arguments
    missing = []
    for name in iterator:
        # Treat None values and empty strings as missing only if the type demands a value
        if name not in args or args[name] is None:
            missing.append(str(name))

    if missing:
        raise ValueError(f"Missing required argument(s): {', '.join(missing)}")

    # If everything is fine, silently return True
    return True<|return|>

def validate_requires_args(self, args):
    """
    Check if all the required arguments have been provided.
    """
    # Retrieve the list/set/tuple of required argument names.
    required_names = getattr(self, "required_args", [])
    if required_names is None:
        required_names = []

    if not isinstance(required_names, (list, set, tuple)):
        raise TypeError("self.required_args must be a list, set, or tuple of argument names.")

    # Ensure args is provided.
    if args is None:
        raise ValueError("No arguments were provided.")

    # Helper to extract a value for a given name from args.
    def get_value(name):
        if isinstance(args, dict):
            return args.get(name, None)
        # If args is an object with attributes (e.g., argparse.Namespace)
        return getattr(args, name, None)

    missing = []
    for name in required_names:
        # Skip if name is not hashable or not a string (allow any hashable)
        try:
            value = get_value(name)
        except Exception:
            value = None
        if value is None:
            missing.append(name)

    if missing:
        raise ValueError(f"Missing required argument(s): {', '.join(map(str, missing))}")<|return|>

def _get_conditionally_required_args(self, command_name, options_spec, args):
    """
    List arguments with ``required_when`` condition matched.

    :param command_name: the command name.
    :param options_spec:  the list of command spec options.
    :param args: the received input arguments
    :return: list, list of argument names with matched ``required_when``
        condition
    """
    # Normalize arguments
    args = {} if args is None else dict(args)
    conditional_required = []

    # Helper to evaluate a condition
    def _evaluate_condition(cond):
        """Return True if the condition holds given command_name and args."""
        try:
            if callable(cond):
                return bool(cond(command_name, args))
            if isinstance(cond, (list, tuple)):
                return all(_evaluate_condition(sub) for sub in cond)
            if isinstance(cond, str):
                # Use args as local variables for eval; no builtins
                return bool(eval(cond, {}, args))
            # Fallback: truthy test of cond itself
            return bool(cond)
        except Exception:
            # Any error in evaluating condition should be treated as False
            return False

    # Iterate over options spec
    for opt in options_spec:
        if not isinstance(opt, dict):
            continue
        name = opt.get("name")
        if not name:
            continue
        if "required_when" not in opt:
            continue
        if _evaluate_condition(opt["required_when"]):
            conditional_required.append(name)

    return conditional_required
