def _get_conditionally_required_args(self, command_name, options_spec,
                                         args):
        """List arguments with ``required_when`` condition matched.

        :param command_name: the command name.
        :param options_spec:  the list of command spec options.
        :param args: the received input arguments
        :return: list, list of argument names with matched ``required_when``
            condition
        """
        # pylint: disable=protected-access
        if not isinstance(args, dict):
            # If args is a list or tuple, try to convert to dict with indices
            try:
                args = {i: v for i, v in enumerate(args)}
            except Exception:
                # Fall back to empty dict to avoid raising unexpectedly
                args = {}

        def _matches(cond, current_args):
            """Recursive matcher for option conditions."""
            # Callable condition
            if callable(cond):
                try:
                    return bool(cond(current_args))
                except Exception:
                    return False
            # List / tuple of conditions (all must match)
            if isinstance(cond, (list, tuple)):
                return all(_matches(c, current_args) for c in cond)
            # Mapping condition (simple expression)
            if isinstance(cond, dict):
                # Expected keys: 'option', 'value', optional 'operator' (default ==)
                opt_name = cond.get("option")
                if opt_name is None:
                    return False
                opt_val = current_args.get(opt_name)
                expected = cond.get("value")
                operator = cond.get("operator", "==")
                if operator == "==":
                    return opt_val == expected
                if operator == "!=":
                    return opt_val != expected
                if operator == "in":
                    return opt_val in expected if isinstance(expected, (list, set, tuple)) else False
                if operator == "not in":
                    return opt_val not in expected if isinstance(expected, (list, set, tuple)) else False
                # Unsupported operator
                return False
            # String condition: treat as truthy presence of argument
            if isinstance(cond, str):
                return bool(current_args.get(cond))
            # Unsupported type
            return False

        result = []
        for spec in options_spec:
            name = spec.get("name")
            if not name:
                continue
            cond = spec.get("required_when")
            if cond is None:
                continue
            try:
                if _matches(cond, args):
                    result.append(name)
            except Exception:
                # If condition evaluation fails, skip this spec
                continue
        return result<|return|>

def validate_length_args(self, args):
    """Check if value of arguments is not longer than length specified.

    :param args: The received arguments.
    :raises TypeError: If args is not a mapping type.
    :raises ValueError: If any argument exceeds its defined maximum length.
    """
    # Ensure args is a mapping
    if not isinstance(args, (dict,)):
        raise TypeError(f"validate_length_args expects a dict, got {type(args).__name__}")

    # Retrieve max_lengths from the instance; it should be a dict mapping arg name to an int max length.
    max_lengths = getattr(self, "max_lengths", {})
    if not isinstance(max_lengths, dict):
        # If the instance attribute is malformed, treat as if no limits.
        max_lengths = {}

    for key, value in args.items():
        # Skip keys that don't have a length restriction
        if key not in max_lengths:
            continue
        max_len = max_lengths[key]

        # Only types that support len() realistically
        if isinstance(value, (str, bytes, list, tuple, set, dict)):
            try:
                actual_len = len(value)
            except Exception:
                # If len() fails, consider it invalid
                raise ValueError(f"Unable to determine length of argument '{key}'")
            if actual_len > max_len:
                raise ValueError(
                    f"Argument '{key}' length {actual_len} exceeds maximum allowed {max_len}"
                )
        else:
            # For non-lengthable types, skip or optionally raise
            # Here we simply skip as there's nothing to validate
            continue
    # No errors found
    return True<|return|>

def validate_length_args(self, args):
    """Check if value of arguments is not longer than length specified.

    :param args: The received arguments.
    :return: None. Raises ValueError if any argument exceeds its allowed length.
    """
    # Ensure instance has a length specification
    if hasattr(self, "limits") and isinstance(self.limits, dict):
        max_len_map = self.limits
    elif hasattr(self, "max_length") and isinstance(self.max_length, int):
        max_len_map = None
    else:
        raise AttributeError(
            "Instance must have a 'limits' dictionary or a single integer 'max_length' attribute to define maximum lengths."
        )

    # args must be a mapping of argument names to values
    if not isinstance(args, dict):
        raise TypeError("args must be a dictionary of argument names to values.")

    errors = []
    for name, value in args.items():
        # Determine applicable maximum length for this argument
        if max_len_map is not None:
            max_len = max_len_map.get(name)
        else:
            max_len = getattr(self, "max_length")

        if max_len is None:
            # No length constraint specified for this argument
            continue

        # Compute the length of the value, converting to string if necessary
        try:
            current_len = len(value) if value is not None else 0
        except TypeError:
            current_len = len(str(value))

        if current_len > max_len:
            errors.append(
                f"Argument '{name}' length {current_len} exceeds maximum allowed {max_len}"
            )

    if errors:
        raise ValueError("; ".join(errors))<|return|>

def validate_length_args(self, args):
    """Check if value of arguments is not longer than length specified.

    :param args: The received arguments. Expected to be a mapping of
                 argument names to their values. Length constraints can
                 be defined per-argument in ``self.arg_max_lengths`` or
                 globally in ``self.max_length``. If the corresponding
                 attribute does not exist, no length check is performed.
    """
    # Basic argument validation
    if args is None:
        raise TypeError("args cannot be None")
    if not isinstance(args, dict):
        raise TypeError(f"args must be a dict, got {type(args).__name__}")

    # Retrieve length constraints
    per_arg_constraints = getattr(self, "arg_max_lengths", {})
    global_constraint = getattr(self, "max_length", None)

    # Ensure constraints are integers (or None)
    if global_constraint is not None and not isinstance(global_constraint, int):
        raise TypeError(f"global max_length must be an int, got {type(global_constraint).__name__}")
    for key, value in per_arg_constraints.items():
        if not isinstance(value, int):
            raise TypeError(f"max length for argument '{key}' must be an int, got {type(value).__name__}")

    # Validate each argument
    for arg_name, arg_value in args.items():
        # Determine applicable constraint
        max_len = per_arg_constraints.get(arg_name, global_constraint)

        # If no constraint specified, skip validation
        if max_len is None:
            continue
        if not isinstance(max_len, int) or max_len < 0:
            # Invalid constraint definition; skip to avoid silent failures
            continue

        # Convert value to string for length measurement
        # Avoid TypeError for non-string objects by casting to str
        try:
            string_rep = str(arg_value) if arg_value is not None else ""
        except Exception as exc:
            raise ValueError(f"Could not convert argument {arg_name!r} to string for length check: {exc}") from exc

        if len(string_rep) > max_len:
            raise ValueError(
                f"Argument '{arg_name}' length {len(string_rep)} exceeds "
                f"maximum allowed {max_len}"
            )<|return|>

def validate_length_args(self, args):
    """Check if value of arguments is not longer than length specified."""
    if not args:
        return
    for idx, arg in enumerate(args):
        # Determine value, max length and a name for reporting
        if isinstance(arg, dict):
            value = arg.get("value")
            max_len = arg.get("max_length") or arg.get("max") or arg.get("length")
            name = arg.get("name", f"argument {idx}")
        else:
            try:
                value = getattr(arg, "value")
            except AttributeError:
                continue
            try:
                max_len = getattr(arg, "max_length")
            except AttributeError:
                try:
                    max_len = getattr(arg, "max")
                except AttributeError:
                    try:
                        max_len = getattr(arg, "length")
                    except AttributeError:
                        max_len = None
            try:
                name = getattr(arg, "name")
            except AttributeError:
                name = f"argument {idx}"
        if max_len is None:
            continue
        if value is None:
            continue
        try:
            actual_len = len(value)
        except TypeError:
            try:
                actual_len = len(str(value))
            except Exception:
                continue
        if actual_len > max_len:
            raise ValueError(f"{name} exceeds maximum length of {max_len}")
<|return|>

def validate_choices_args(self, args):
    """
    Check if value of choice arguments is one of the available choices.

    The method attempts to validate each argument in ``args`` against
    the ``choices`` specification provided by the calling class.
    It supports three common patterns for how the choice specification may be
    stored:

    1. ``self.options`` – a mapping from argument names to option info
       dictionaries that may contain a ``'choices'`` key.
    2. ``self.choices`` – a mapping from argument names to an iterable
       of allowed values.
    3. An attribute on ``self`` with the same name as the argument that
       itself has a ``choices`` attribute.

    If the value for an argument is not in the supplied set of allowed
    choices, a :class:`ValueError` is raised with a helpful message.
    Arguments that have no associated ``choices`` specification are ignored.

    Parameters
    ----------
    args : Mapping[str, Any]
        The parsed arguments, usually a dict returned by ``argparse``.
    """
    # Guard against non-mapping inputs
    if not isinstance(args, dict):
        raise TypeError("args must be a mapping of argument names to values")

    # Helper to fetch choices from various possible places
    def _fetch_choices(name):
        # 1. Options dictionary
        opt = getattr(self, "options", None)
        if isinstance(opt, dict):
            info = opt.get(name)
            if isinstance(info, dict):
                return info.get("choices")

        # 2. Explicit choices mapping
        ch = getattr(self, "choices", None)
        if isinstance(ch, dict):
            return ch.get(name)

        # 3. Attribute on self
        attr = getattr(self, name, None)
        if hasattr(attr, "choices"):
            return getattr(attr, "choices")

        return None

    for arg_name, value in args.items():
        # Skip if the argument was omitted or left to its default
        if value is None:
            continue

        allowed = _fetch_choices(arg_name)
        if allowed is None:
            # No choices defined for this argument; nothing to validate
            continue

        # Normalize allowed to a set for efficient membership test
        try:
            allowed_set = set(allowed)
        except TypeError:
            # Non-iterable; treat as a single allowed value
            allowed_set = {allowed}

        # For list-like values (e.g., multiple selections) validate each item
        if isinstance(value, (list, set, tuple)):
            invalid_items = [v for v in value if v not in allowed_set]
            if invalid_items:
                raise ValueError(
                    f"Invalid value(s) for argument '{arg_name}': {invalid_items}. "
                    f"Allowed choices are {sorted(allowed_set)}"
                )
        else:
            if value not in allowed_set:
                raise ValueError(
                    f"Invalid value for argument '{arg_name}': {value}. "
                    f"Allowed choices are {sorted(allowed_set)}"
                )<|return|>

def validate_choices_args(self, args):
        """Check if value of choice arguments is one of the available choices.

        :param args: The received arguments (expected as a mapping of argument names to values).
        :raises ValueError: If any value is not among the permitted choices.
        """
        # If the instance does not provide a mapping of available choices, nothing to validate.
        if not hasattr(self, "choices") or not isinstance(self.choices, dict):
            return

        for key, value in args.items():
            # Skip arguments that don't have predefined choices
            if key not in self.choices:
                continue

            allowed = self.choices[key]
            # Allow None or empty values when the argument is optional
            if value is None:
                continue

            # If the value is iterable (but not a string), validate each element
            if isinstance(value, (list, tuple, set)):
                for v in value:
                    if v not in allowed:
                        raise ValueError(
                            f"Invalid value for argument '{key}': {v!r}. "
                            f"Expected one of {allowed!r}."
                        )
                continue

            # For scalar values, validate directly
            if value not in allowed:
                raise ValueError(
                    f"Invalid value for argument '{key}': {value!r}. "
                    f"Expected one of {allowed!r}."
                )<|return|>

def validate_choices_args(self, args):
        """Check if value of choice arguments is one of the available choices.

        :param args: The received arguments.
        """
        # Validate args type
        if not isinstance(args, dict):
            raise TypeError(
                f"args must be a dictionary of argument names to values, got {type(args).__name__}"
            )

        # Retrieve the mapping of valid choices for each argument
        choices_map = getattr(self, "choices", {})
        if not isinstance(choices_map, dict):
            raise AttributeError(
                "Expected attribute 'choices' to be a dictionary mapping argument names to allowed values"
            )

        for name, value in args.items():
            # Skip arguments that don't have predefined choices
            if name not in choices_map:
                continue

            allowed = choices_map[name]

            # If multiple values are allowed for this argument (list/tuple input),
            # check each value individually.
            if isinstance(value, (list, tuple)):
                if not isinstance(allowed, (list, tuple, set)):
                    # Expected a single allowed value but a list of values was passed
                    raise ValueError(
                        f"Argument '{name}' expects a single value but received a list/tuple"
                    )
                invalid_vals = [v for v in value if v not in allowed]
                if invalid_vals:
                    raise ValueError(
                        f"Invalid choices for argument '{name}': {invalid_vals}. "
                        f"Allowed: {allowed}"
                    )
            else:
                # For scalar values simply check membership
                if isinstance(allowed, (list, tuple, set)):
                    if value not in allowed:
                        raise ValueError(
                            f"Invalid choice for argument '{name}': {value}. Allowed: {allowed}"
                        )
                else:
                    if value != allowed:
                        raise ValueError(
                            f"Invalid choice for argument '{name}': {value}. Allowed: {allowed}"
                        )<|return|>

def validate_choices_args(self, args):
    """
    Check if value of choice arguments is one of the available choices.

    :param args: The received arguments.
    """
    # Retrieve the mapping of argument names to allowed values.
    choices_map = getattr(self, "choices", {})
    if not isinstance(choices_map, dict):
        raise TypeError("Choices attribute must be a dictionary mapping argument names to iterable of allowed values.")
    for arg_name, valid_values in choices_map.items():
        # Skip validation if no valid values are provided.
        if not hasattr(valid_values, "__iter__"):
            raise TypeError(f"Valid values for argument '{arg_name}' must be iterable.")
        # Resolve the actual argument value from the passed args.
        try:
            if isinstance(args, dict):
                value = args.get(arg_name)
            else:
                value = getattr(args, arg_name, None)
        except Exception as exc:
            raise ValueError(f"Error accessing argument '{arg_name}': {exc}") from exc
        # Skip if the argument is not present.
        if value is None:
            continue
        # If the value itself is iterable (e.g., list of selections), validate each element.
        if isinstance(value, (list, tuple, set)):
            for v in value:
                if v not in valid_values:
                    raise ValueError(f"Invalid choice '{v}' for argument '{arg_name}'. "
                                     f"Expected one of {list(valid_values)}.")
        else:
            if value not in valid_values:
                raise ValueError(f"Invalid choice '{value}' for argument '{arg_name}'. "
                                 f"Expected one of {list(valid_values)}.")<|return|>

def validate_min_max_args(self, args):
    """Check if value of arguments is between minimum and maximum values.

    :param args: The received arguments.
    """
    if args is None:
        raise TypeError("args cannot be None")

    # Helper to validate a single argument dict
    def _check(arg_name, arg_dict):
        if not isinstance(arg_dict, dict):
            raise TypeError(f"Argument '{arg_name}' must be a dict, got {type(arg_dict).__name__}")
        if 'value' not in arg_dict:
            raise KeyError(f"Argument '{arg_name}' missing required 'value' key")
        value = arg_dict['value']
        if not isinstance(value, (int, float)):
            raise TypeError(f"Value of argument '{arg_name}' must be a number, got {type(value).__name__}")
        min_val = arg_dict.get('min', -float("inf"))
        max_val = arg_dict.get('max', float("inf"))
        if not isinstance(min_val, (int, float)):
            raise TypeError(f"Minimum bound for argument '{arg_name}' must be a number, got {type(min_val).__name__}")
        if not isinstance(max_val, (int, float)):
            raise TypeError(f"Maximum bound for argument '{arg_name}' must be a number, got {type(max_val).__name__}")
        if value < min_val or value > max_val:
            raise ValueError(
                f"Argument '{arg_name}' value {value} is outside bounds [{min_val}, {max_val}]"
            )

    # Dictionary of argument names to dicts
    if isinstance(args, dict):
        for name, arg_dict in args.items():
            _check(name, arg_dict)

    # List or tuple of argument dicts
    elif isinstance(args, (list, tuple)):
        for idx, arg_dict in enumerate(args):
            if not isinstance(arg_dict, dict):
                raise TypeError(
                    f"Element {idx} in args list must be a dict, got {type(arg_dict).__name__}"
                )
            if 'name' not in arg_dict:
                raise KeyError(f"Element {idx} missing required 'name' key")
            name = arg_dict['name']
            _check(name, arg_dict)

    else:
        raise TypeError(
            f"args must be a dict or list/tuple of dicts, got {type(args).__name__}"
        )
    # If all checks pass, function returns None (implicitly).<|return|>

def validate_min_max_args(self, args):
        """
        Check if value of arguments is between minimum and maximum values.

        :param args: The received arguments. Can be a single numeric value, an iterable of
                     numeric values, or a mapping whose values will be validated.
        """
        # Ensure that the instance defines required bounds
        if not hasattr(self, "min_value") or not hasattr(self, "max_value"):
            raise AttributeError(
                "Object must define 'min_value' and 'max_value' attributes."
            )

        min_val = self.min_value
        max_val = self.max_value

        # Helper to validate a single numeric value
        def _check(val):
            if not isinstance(val, (int, float)):
                raise TypeError(f"Argument {val!r} is not numeric.")
            if val < min_val or val > max_val:
                raise ValueError(
                    f"Argument {val!r} is outside the allowed range [{min_val}, {max_val}]."
                )

        # If args is a mapping, validate its values
        if isinstance(args, dict):
            for key, value in args.items():
                _check(value)

        # If args is an iterable but not a string/bytes
        elif isinstance(args, (list, tuple, set)):
            for value in args:
                _check(value)

        # Otherwise treat args as a single value
        else:
            _check(args)

        return True<|return|>

def validate_min_max_args(self, args):
    """Check if value of arguments is between minimum and maximum values."""
    # Determine the min and max bounds that should be defined on the instance.
    if not hasattr(self, 'min_value') or not hasattr(self, 'max_value'):
        raise AttributeError("Instance must have 'min_value' and 'max_value' attributes.")
    min_val, max_val = self.min_value, self.max_value
    if not isinstance(min_val, (int, float)) or not isinstance(max_val, (int, float)):
        raise TypeError("min_value and max_value must be numeric types.")
    if min_val > max_val:
        raise ValueError(f"min_value ({min_val}) cannot be greater than max_value ({max_val}).")

    if args is None:
        raise ValueError("Argument 'args' cannot be None.")

    def _check_value(val, key=None, idx=None):
        if not isinstance(val, (int, float)):
            identifier = f"'{key}'" if key is not None else f"index {idx}"
            raise TypeError(f"Argument {identifier} has non-numeric value: {val!r}")
        if val < min_val or val > max_val:
            identifier = f"'{key}'" if key is not None else f"index {idx}"
            raise ValueError(f"Argument {identifier} with value {val!r} is out of bounds "
                             f"[{min_val}, {max_val}].")

    # Support dict, list/tuple, or a single value.
    if isinstance(args, dict):
        for key, val in args.items():
            _check_value(val, key=key)
    elif isinstance(args, (list, tuple)):
        for idx, val in enumerate(args):
            _check_value(val, idx=idx)
    else:
        _check_value(args)

    return True<|return|>

def validate_min_max_args(self, args):
    """Check if value of arguments is between minimum and maximum values.

    :param args: The received arguments. Can be either a dict with keys
        ``'value'``, ``'min'`` and ``'max'``, or a tuple/list containing
        ``(value, min, max)`` in that order.
    :return: True if the value lies between min and max (inclusive),
              False otherwise or if the input is malformed.
    """
    try:
        # Retrieve value, min, and max from the input
        if isinstance(args, dict):
            if not {'value', 'min', 'max'}.issubset(args):
                return False
            value, min_val, max_val = args['value'], args['min'], args['max']
        elif isinstance(args, (tuple, list)) and len(args) == 3:
            value, min_val, max_val = args
        else:
            return False

        # Ensure all three are numeric (int or float)
        if not all(isinstance(v, (int, float)) for v in (value, min_val, max_val)):
            return False

        # Reject if min is greater than max
        if min_val > max_val:
            return False

        # Check inclusivity
        return min_val <= value <= max_val
    except Exception:
        return False<|return|>

def get_nested_custom_and_control_args(self, args):
        """
        Split input arguments into control, nested, and custom categories.

        Controls arguments: control the IR behavior. These arguments
            will not be put into the spec yml file.
        Nested arguments: are used by the Ansible playbooks and will be put
            into the spec yml file.
        Custom arguments: Custom ansible variables to be used instead of the
            normal nested usage.

        The method accepts `args` in several common forms:
        - A dictionary of ``{key: value}``.
        - A list (or tuple) of ``(key, value)`` pairs.
        - A list (or tuple) of strings in the form ``"key=value"``.

        Any keys that start with ``"control_"`` are collected in
        ``control_args``; all other keys are collected in ``nested_args``,
        including those that start with ``"custom_"``.  Keys that do not
        match either pattern are added verbatim to ``nested_args``.

        :param args: The collected list/dict of args.
        :return: A 2-tuple (control_args, nested_args) where both are flat
                 dictionaries.
        """
        # Prepare containers
        control_args = {}
        nested_args = {}

        # Helper to process a key/value pair
        def _add_pair(key, value):
            if not key:
                # skip empty keys
                return
            if key.startswith("control_"):
                # Normalize: strip the prefix? According to the original
                # description control args are not written to the spec.
                # We keep the original key for consistency.
                control_args[key] = value
            else:
                # All other keys, including custom_, go into nested_args
                nested_args[key] = value

        # Normalize args into iterable of pairs
        if args is None:
            iterator = []
        elif isinstance(args, dict):
            iterator = args.items()
        elif isinstance(args, (list, tuple)):
            # Detect if list of tuples or strings
            iterator = []
            for item in args:
                if isinstance(item, (tuple, list)):
                    if len(item) == 2:
                        iterator.append((item[0], item[1]))
                    else:
                        raise ValueError(f"Tuple/list {item} does not have exactly 2 elements")
                elif isinstance(item, str):
                    # Split on first '='
                    if "=" in item:
                        key, value = item.split("=", 1)
                        iterator.append((key, value))
                    else:
                        raise ValueError(f"String argument '{item}' is not a valid key=value pair")
                else:
                    raise ValueError(f"Unsupported argument type: {type(item).__name__}")
        else:
            raise ValueError(f"Unsupported args type: {type(args).__name__}")

        # Process each pair
        for key, value in iterator:
            _add_pair(key, value)

        return control_args, nested_args}<|return|>

def get_nested_custom_and_control_args(self, args):
    """
    Split input arguments to control nested and custom.

    Controls arguments: control the IR behavior. These arguments
        will not be put into the spec yml file
    Nested arguments: are used by the Ansible playbooks and will be put
        into the spec yml file.
    Custom arguments: Custom ansible variables to be used instead of the
        normal nested usage.

    :param args: the collected list of args.
    :return: (dict, dict): flat dicts (control_args, nested_args)
    """
    # Initialise result dictionaries
    control_args = {}
    nested_args = {}

    # Validate input
    if args is None:
        return control_args, nested_args

    # Accept mapping or a list of pairs
    if isinstance(args, dict):
        items = args.items()
    else:
        try:
            # Expected to be an iterable of (key, value) pairs
            items = iter(args)
        except TypeError:
            # Invalid input - return empty dicts
            return control_args, nested_args

    for item in items:
        # Attempt to unpack key/value
        if isinstance(item, tuple) and len(item) == 2:
            key, value = item
        else:
            # Skip malformed entries
            continue

        if not isinstance(key, str):
            # Skip non-string keys
            continue

        # Determine if argument is a control argument
        if key.lower().startswith("control_"):
            control_args[key] = value
        else:
            nested_args[key] = value

    return control_args, nested_args<|return|>

def get_nested_custom_and_control_args(self, args):
    """
    Split input arguments to control nested and custom.

    Controls arguments: control the IR behavior. These arguments
        will not be put into the spec yml file
    Nested arguments: are used by the Ansible playbooks and will be put
        into the spec yml file.
    Custom arguments: Custom ansible variables to be used instead of the
        normal nested usage.

    :param args: the collected list of args. It may be a dict or a list
       /tuple of (key, value) pairs.
    :return: (dict, dict): flat dicts (control_args, nested_args)
    """
    # Normalise input to iterable of key/value pairs
    if args is None:
        items = []
    elif isinstance(args, dict):
        items = list(args.items())
    elif isinstance(args, (list, tuple)):
        # Accept list of tuples/2-element lists or dict-like objects
        items = []
        for item in args:
            if isinstance(item, (tuple, list)) and len(item) == 2:
                items.append((item[0], item[1]))
            else:
                raise TypeError(f"Unsupported item in args list: {item!r}")
    else:
        raise TypeError(f"Unsupported type for args: {type(args)!r}")

    control_args = {}
    nested_args = {}

    for key, val in items:
        if key is None:
            continue
        if not isinstance(key, str):
            key_str = str(key)
        else:
            key_str = key

        # If a key is explicitly marked as control (prefix or part of a known
        # list) then it is added to the control dict.
        key_lower = key_str.lower()
        if key_lower.startswith("control_") or key_lower in ("debug", "verbose", "-c"):
            control_args[key_str] = val
        # Custom arguments are prefixed with "custom_". They are merged
        # into the nested dict but with the "custom_" prefix stripped; the
        # original full key is preserved as a fallback.
        elif key_lower.startswith("custom_"):
            nested_key = key_str[7:]  # strip 'custom_'
            # If the nested key is empty just keep the original.
            nested_key = nested_key or key_str
            nested_args[nested_key] = val
        else:
            # Default: nested argument
            nested_args[key_str] = val

    return control_args, nested_args
<|return|>

def get_nested_custom_and_control_args(self, args):
    """Split input arguments into control arguments and nested (including custom) arguments.

    Controls arguments: control the IR behaviour and are not written
    to the spec yml file.
    Nested arguments: used by Ansible playbooks and are written to the
    spec yml file.
    Custom arguments: ansible variables prefixed with ``custom_``.
    They are written to the nested dict but with the ``custom_`` prefix
    stripped.

    Parameters
    ----------
    args : dict | list[str]
        Collected arguments.  If a dict, keys and values are taken
        directly.  If a list, each element must be a ``key=value`` string.
        ``key`` without ``=`` is interpreted as a boolean flag ``True``.

    Returns
    -------
    tuple[dict, dict]
        Two flat dictionaries: ``(control_args, nested_args)``

    Raises
    ------
    TypeError
        If *args* is not a dict or list.
    ValueError
        If a list element is not a ''key=value'' pair.
    """
    if not args:
        return {}, {}

    # Determine the set of recognised control arguments.  If the
    # caller class exposes an attribute ``CONTROL_ARGS`` use it;
    # otherwise fall back to an empty set.
    control_set = getattr(self, "CONTROL_ARGS", set())

    control_args = {}
    nested_args = {}

    def _add(arg_key, arg_val):
        """Add a raw key/value pair into the appropriate dictionary."""
        if arg_key in control_set:
            control_args[arg_key] = arg_val
        else:
            # Handle custom prefixes
            if arg_key.startswith("custom_"):
                # strip the custom prefix
                arg_key = arg_key[len("custom_") :]
            nested_args[arg_key] = arg_val

    if isinstance(args, dict):
        for key, value in args.items():
            if not isinstance(key, str):
                raise ValueError("Argument keys must be strings")
            _add(key, value)
    elif isinstance(args, list):
        for item in args:
            if not isinstance(item, str):
                raise ValueError("List items must be strings of form 'key=value'")
            if "=" in item:
                key, val = item.split("=", 1)
                key = key.strip()
                val = val.strip()
                # Try to interpret simple literals
                if val.lower() == "true":
                    val = True
                elif val.lower() == "false":
                    val = False
                elif val.lower() == "none":
                    val = None
                _add(key, val)
            else:
                # No '=', interpret as a flag
                key = item.strip()
                _add(key, True)
    else:
        raise TypeError("args must be a dict or a list of strings")

    return control_args, nested_args

