def get_nested_custom_and_control_args(self, args):
    """
    Split input arguments to control, nested and custom.

    Controls arguments: control the IR behavior. These arguments
        will not be put into the spec yml file
    Nested arguments: are used by the Ansible playbooks and will be put
        into the spec yml file.
    Custom arguments: Custom ansible variables to be used instead of the
        normal nested usage.

    :param args: the collected list of args, can be a dict, a list of
        key/value strings or tuple pairs.
    :return: tuple (control_args: dict, nested_args: dict)
    """
    # Normalize the input into a flat dictionary
    args_dict = {}
    try:
        if isinstance(args, dict):
            args_dict = dict(args)  # copy to avoid side‑effects
        elif isinstance(args, (list, tuple)):
            # Work with list of items.  It may be key/value pairs or
            # strings like "key=value".
            # If the list length is even, assume alternating key/value
            if len(args) % 2 == 0:
                it = iter(args)
                for key in it:
                    try:
                        value = next(it)
                    except StopIteration:
                        break
                    if isinstance(key, str):
                        key = key.lstrip("- ").strip()
                    if isinstance(value, str):
                        value = value.strip()
                    if key:
                        args_dict[key] = value
            else:
                # Assume each item is a string in the form key=value
                for item in args:
                    if not isinstance(item, str):
                        continue
                    if "=" in item:
                        key, value = item.split("=", 1)
                        key = key.lstrip("- ").strip()
                        value = value.strip()
                        if key:
                            args_dict[key] = value
        else:
            # Try to iterate through an arbitrary iterator
            for item in args:
                if not isinstance(item, str):
                    continue
                if "=" in item:
                    key, value = item.split("=", 1)
                    key = key.lstrip("- ").strip()
                    value = value.strip()
                    if key:
                        args_dict[key] = value
    except Exception:
        # If anything goes wrong, fall back to an empty dict
        args_dict = {}

    # Split the dictionary into control and nested arguments
    control_args = {}
    nested_args = {}
    for key, value in args_dict.items():
        # Treat keys starting with "control" (case‑insensitive) as control
        if isinstance(key, str) and key.lower().startswith("control"):
            control_args[key] = value
        else:
            nested_args[key] = value

    return control_args, nested_args<|return|>

