@staticmethod
def merge_extra_vars(vars_dict, extra_vars=None):
    """
    Extend ``vars_dict`` with ``extra-vars``.

    :param vars_dict: Dictionary to merge extra-vars into
    :param extra_vars: List of extra-vars (strings or dictionaries)
    :return: Updated dictionary
    """
    if not isinstance(vars_dict, dict):
        raise TypeError("vars_dict must be a dictionary")
    # If no extra variables provided, return dictionary as-is
    if not extra_vars:
        return vars_dict
    # Work on a copy to avoid mutating the original dict
    merged = vars_dict.copy()
    for item in extra_vars:
        if isinstance(item, dict):
            # Merge dictionary items directly
            merged.update(item)
        elif isinstance(item, str):
            # Split on first '=' or ':' if present
            split_char = None
            if "=" in item:
                split_char = "="
            elif ":" in item:
                split_char = ":"
            if not split_char:
                # Not a valid key-value string; ignore it
                continue
            parts = item.split(split_char, 1)
            if len(parts) != 2:
                continue
            key, value = parts[0].strip(), parts[1].strip()
            if key:
                merged[key] = value
        else:
            # Unsupported type; ignore silently
            continue
    return merged<|return|>

@staticmethod
def merge_extra_vars(vars_dict, extra_vars=None):
    """
    Extend ``vars_dict`` with ``extra-vars``.

    The method accepts a dictionary ``vars_dict`` and an optional
    ``extra_vars`` parameter that may be ``None``, a dictionary, a
    sequence of strings or a single string.  Each string is assumed to
    be in the form ``key=value``; if the value contains an ``=`` the
    first one is considered the split point and the remainder is
    treated as the value.  Keys are added to ``vars_dict`` and existing
    keys are overwritten.  The updated dictionary is returned.

    Any values that cannot be parsed are stored as strings.

    :param vars_dict: Dictionary to merge extra-vars into.
    :param extra_vars: Extra variables to merge; may be ``None``,
                       a dictionary, a string, or a sequence of
                       ``key=value`` strings.
    :returns: The merged dictionary.
    """
    if not isinstance(vars_dict, dict):
        raise TypeError("vars_dict must be a dict")

    if extra_vars is None:
        return vars_dict

    # Helper to process a single key-value pair string
    def _process_pair(pair: str):
        if not isinstance(pair, str):
            return
        if '=' not in pair:
            # No '=' -> treat as key with empty string value
            key = pair.strip()
            value = ''
        else:
            key, value = pair.split('=', 1)
            key = key.strip()
            value = value.strip()
        # Avoid empty keys
        if key:
            vars_dict[key] = value

    if isinstance(extra_vars, dict):
        # Merge dictionary directly
        for k, v in extra_vars.items():
            vars_dict[k] = v
    elif isinstance(extra_vars, (list, tuple)):
        for element in extra_vars:
            _process_pair(element)
    elif isinstance(extra_vars, str):
        for token in extra_vars.split():
            _process_pair(token)
    else:
        # Unsupported type; ignore
        pass

    return vars_dict<|return|>

@staticmethod
def merge_extra_vars(vars_dict, extra_vars=None):
    """Extend ``vars_dict`` with ``extra-vars``

    :param vars_dict: Dictionary to merge extra-vars into
    :param extra_vars: List of extra-vars
    """
    if not isinstance(vars_dict, dict):
        raise TypeError("vars_dict must be a dictionary")
    if extra_vars is None:
        return vars_dict

    def _convert_value(val):
        """Safely convert string to a python literal if possible."""
        import ast
        try:
            return ast.literal_eval(val)
        except Exception:
            return val

    def _parse_str(item):
        """Parse a string of the form 'key=value' or 'key: value'."""
        if isinstance(item, str):
            for sep in ("=", ":"):
                if sep in item:
                    key, val = item.split(sep, 1)
                    key = key.strip()
                    if not key:
                        return None
                    val = val.strip()
                    return (key, _convert_value(val))
        return None

    if isinstance(extra_vars, dict):
        vars_dict.update(extra_vars)
    elif isinstance(extra_vars, (list, tuple, set)):
        for element in extra_vars:
            if isinstance(element, dict):
                vars_dict.update(element)
            else:
                parsed = _parse_str(element)
                if parsed:
                    k, v = parsed
                    vars_dict[k] = v
    else:
        raise TypeError(
            "extra_vars must be None, a dict, or an iterable of dicts/strings"
        )
    return vars_dict<|return|>

