def _convert_non_cli_args(self, parser_name, values_dict):
        """
        Casts arguments to correct types by modifying values_dict in place.

        The method first attempts to use a predefined type map for the given
        parser.  The type map should be a dictionary on the instance with the
        form ``{parser_name: {arg_name: type_or_callable, ...}, ...}``.  
        If a type or callable is specified, it is used to convert the string
        value; otherwise the method falls back to an automatic conversion
        strategy that infers booleans, integers, floats, comma separated
        lists, and leaves everything else as a string.

        The conversion can handle nested dictionaries: any nested mapping
        will be processed recursively.

        Parameters
        ----------
        parser_name : str
            Name of the command/parser (e.g. ``main``, ``virsh``, ``ospd``).
        values_dict : dict
            Dictionary of argument names to CLI string values.  The values
            will be modified in place.
        """
        def _convert_value(val, target=None):
            """Convert a single value using an optional target type."""
            if target is None:
                # Handle fundamental types automatically
                if isinstance(val, str):
                    s = val.strip()
                    # Empty string → None
                    if s == '':
                        return None
                    # Boolean
                    lowered = s.lower()
                    if lowered in {'true', '1'}:
                        return True
                    if lowered in {'false', '0'}:
                        return False
                    # None literal
                    if lowered == 'none':
                        return None
                    # Integer
                    if s.isdigit() or (s.startswith('-') and s[1:].isdigit()):
                        try:
                            return int(s)
                        except ValueError:
                            pass
                    # Float
                    try:
                        return float(s)
                    except ValueError:
                        pass
                    # Comma-separated list
                    if ',' in s:
                        parts = [p.strip() for p in s.split(',')]
                        # Try to convert each part
                        converted_parts = []
                        for p in parts:
                            if p.lower() in {'true', 'false'}:
                                converted_parts.append(p.lower() == 'true')
                            else:
                                try:
                                    converted_parts.append(int(p))
                                except ValueError:
                                    try:
                                        converted_parts.append(float(p))
                                    except ValueError:
                                        converted_parts.append(p)
                        return converted_parts
                    # Default: keep as string
                    return s
                # If not a string, return unchanged
                return val
            else:
                # User supplied conversion
                if callable(target):
                    try:
                        return target(val)
                    except Exception:
                        # Fall back to original value if conversion fails
                        return val
                if isinstance(target, type):
                    try:
                        return target(val)
                    except Exception:
                        return val
                # Unsupported target, return original
                return val

        # Determine type mappings for this parser, if any
        type_map = {}
        if hasattr(self, 'parser_arg_types'):
            parser_map = getattr(self, 'parser_arg_types')
            if isinstance(parser_map, dict):
                type_map = parser_map.get(parser_name, {})
        elif hasattr(self, 'argument_type_map'):
            parser_map = getattr(self, 'argument_type_map')
            if isinstance(parser_map, dict):
                type_map = parser_map.get(parser_name, {})

        # Helper to process each dictionary entry
        def _process_dict(d):
            if not isinstance(d, dict):
                return d
            for k, v in d.items():
                # Determine desired conversion target
                target = type_map.get(k)
                # Recursively handle nested structures
                if isinstance(v, dict):
                    d[k] = _process_dict(v)
