    """Casts arguments to correct types by modifying `values_dict` in place.

    By default, all the values are strings. This method attempts to
    interpret string values as booleans, integers or floats where
    appropriate, leaving other values untouched. If ``parser_name`` is
    needed for custom conversions in subclasses, they can be added
    without changing the public interface.

    :param parser_name: The command name, e.g. 'main', 'virsh', 'ospd', etc.
    :param values_dict: A dictionary mapping argument names to string
                        values that may need type conversion.
    :return: The same dictionary object for chaining convenience.
    """
    # Helper to convert a single value
    def _convert_value(v):
        if v is None:
            return None
        if not isinstance(v, str):
            return v  # already a typed value
        # Strip surrounding whitespace
        t_val = v.strip()
        # Bool conversion
        low = t_val.lower()
        if low in ('true', 't', 'yes', 'y', '1'):
            return True
        if low in ('false', 'f', 'no', 'n', '0'):
            return False
        # Integer conversion
        try:
            # Reject strings like '01' if you want to avoid octal confusion;
            # however many parsers accept leading zeros, so we keep it.
            if t_val.startswith(('0x', '0X')):
                return int(t_val, 16)
            if t_val.startswith(('0o', '0O')):
                return int(t_val, 8)
            if t_val.startswith(('0b', '0B')):
                return int(t_val, 2)
            return int(t_val)
        except ValueError:
            pass
        # Float conversion
        try:
            return float(t_val)
        except ValueError:
            pass
        # Default: keep original string
        return v

    # Convert in place, handling potential nested structures
    for key in list(values_dict.keys()):
        val = values_dict[key]
        # If the value is a list or tuple, try to convert each element
        if isinstance(val, (list, tuple)):
            converted = [_convert_value(v) for v in val]
            values_dict[key] = type(val)(converted)
        else:
            values_dict[key] = _convert_value(val)

    return values_dict<|return|>

def _convert_non_cli_args(self, parser_name, values_dict):
        """
        Cast arguments to correct types by modifying values_dict in-place.

        By default all the values are strings. The conversion tries to convert a
        string into a boolean, integer, or floating point number when that is
        appropriate.  If a value already has the right type it is left untouched.
        Nested dictionaries are processed recursively.

        :param parser_name: The command name, e.g. main, virsh, ospd, etc
        :param values_dict: The dict of arguments to be cast
