            low = val.lower()
            if low == "true":
                return True
            if low == "false":
                return False

            # Integer conversion
            try:
                int_val = int(val)
                return int_val
            except ValueError:
                pass

            # Float conversion
            try:
                float_val = float(val)
                return float_val
            except ValueError:
                pass

            # Leave other strings unchanged
            return val

        # Protect against malformed input (e.g., values_dict not a dict)
        if not isinstance(values_dict, dict):
            raise TypeError(f"_convert_non_cli_args expects a dict, got {type(values_dict).__name__}")

        try:
            for key in values_dict:
                values_dict[key] = _convert_value(values_dict[key])
