def _convert_non_cli_args(self, parser_name, values_dict):
    """
    Casts arguments to correct types by modifying values_dict param.

    By default all the values are strings.

    :param parser_name: The command name, e.g. main, virsh, ospd, etc
    :param values_dict: The dict of arguments
    :return: The modified values_dict with values cast to the correct types.
    """
    # Normalise parser name
    if not isinstance(parser_name, str) or not parser_name:
        raise ValueError(f"Invalid parser_name: {parser_name!r}")

    if not isinstance(values_dict, dict):
        raise TypeError(f"values_dict must be a dictionary, got {type(values_dict)}")

    # Define type mappings for each parser; extend as needed
    _TYPE_MAPPINGS = {
        # Main command parser examples
        "main": {
            "count": int,
            "timeout": float,
            "verbose": bool,
            "names": list,  # expects comma-separated string
            "mode": str,
        },
        # virsh parser examples
        "virsh": {
            "domain": str,
            "state": str,
            "force": bool,
            "priority": int,
        },
        # ospd parser examples
        "ospd": {
            "host": str,
            "port": int,
            "secure": bool,
            "paths": list,  # comma-separated
        },
    }

    # Helper to convert boolean values
    def _to_bool(val):
        if isinstance(val, bool):
            return val
        if isinstance(val, str):
            val_lower = val.strip().lower()
            if val_lower in {"true", "1", "yes", "y"}:
                return True
            if val_lower in {"false", "0", "no", "n"}:
                return False
        if isinstance(val, (int, float)):
            return bool(val)
        raise ValueError(f"Cannot convert {val!r} to bool")

    # Helper to convert list values
    def _to_list(val):
        if isinstance(val, list):
            return val
        if isinstance(val, str):
            return [item.strip() for item in val.split(",") if item.strip()]
        raise ValueError(f"Cannot convert {val!r} to list")

    field_types = _TYPE_MAPPINGS.get(parser_name)
    if field_types is None:
        raise ValueError(f"Unknown parser_name: {parser_name!r}")

    for field, caster in field_types.items():
        if field not in values_dict:
            continue  # skip missing keys; they may be optional
        raw_val = values_dict[field]
        try:
            if raw_val is None:
                # leave None as is
                continue
            if caster is bool:
                cast_val = _to_bool(raw_val)
            elif caster is list:
                cast_val = _to_list(raw_val)
            else:
                cast_val = caster(raw_val)
            values_dict[field] = cast_val
        except Exception as exc:
            raise ValueError(
                f"Failed to convert value for '{field}' "
                f"to {caster.__name__ if hasattr(caster, '__name__') else str(caster)} "
                f"for parser '{parser_name}'. Original value: {raw_val!r}"
            ) from exc

    return values_dict<|return|>

def _convert_non_cli_args(self, parser_name, values_dict):
        """
        Casts arguments to correct types by modifying values_dict param.

        By default all the values are strings.

        :param parser_name: The command name, e.g. main, virsh, ospd, etc
        :param values_dict: The dict of with arguments
        """
        if not isinstance(values_dict, dict):
            raise ValueError(f"values_dict must be a dict, got {type(values_dict)}")

        # Helper to parse individual strings
        def _parse(val):
            if isinstance(val, str):
                stripped = val.strip()
                if not stripped:
                    return stripped
                # Try integer
                try:
                    return int(stripped)
                except ValueError:
                    pass
                # Try float
                try:
                    return float(stripped)
                except ValueError:
                    pass
                # Try boolean
                low = stripped.lower()
                if low in ("true", "1", "yes", "on"):
                    return True
                if low in ("false", "0", "no", "off"):
                    return False
                # Try comma separated list
                if "," in stripped:
                    return [_parse(part.strip()) for part in stripped.split(",")]
                # Return the string itself
                return stripped
            # For non-string values, keep as is
            return val

        for key, value in list(values_dict.items()):
            # Only attempt to convert if the value is a string
            if isinstance(value, str):
                try:
                    converted = _parse(value)
                    values_dict[key] = converted
                except Exception:
                    # On any failure, keep the original value
                    values_dict[key] = value
        # Method modifies values_dict in place; no return needed
        return None<|return|>

def get_plugin_spec_flatten_dict(plugin_dir):
    """Creates a flat dict from the plugin spec

    :param plugin_dir: A path to the plugin's dir
    :return: A flatten dictionary contains the plugin's properties
    """
    # Dynamically import required modules without adding import statements
    os = __import__('os')
    json_mod = __import__('json')
    try:
        yaml_mod = __import__('yaml')
    except Exception:
        yaml_mod = None

    # Validate plugin_dir
    if not isinstance(plugin_dir, (str, bytes)):
        raise TypeError(f"plugin_dir must be a string or path-like, got {type(plugin_dir)!r}")
    if not os.path.isdir(plugin_dir):
        raise ValueError(f"Provided plugin_dir '{plugin_dir}' is not a valid directory")

    # Candidate spec filenames in order of preference
    candidates = [
        "plugin.yaml", "plugin.yml", "spec.yaml", "spec.yml",
        "plugin.json", "spec.json"
    ]

    spec_path = None
    for name in candidates:
        path = os.path.join(plugin_dir, name)
        if os.path.isfile(path):
            spec_path = path
            break

    if not spec_path:
        raise FileNotFoundError(f"No plugin spec file found in '{plugin_dir}'. "
                                f"Tried: {', '.join(candidates)}")

    # Load the spec file
    try:
        with open(spec_path, 'r', encoding='utf-8') as f:
            content = f.read()
    except Exception as exc:
        raise IOError(f"Error reading spec file '{spec_path}': {exc}") from exc

    try:
        if spec_path.lower().endswith(('.yaml', '.yml')) and yaml_mod:
            spec_dict = yaml_mod.safe_load(content)
        elif spec_path.lower().endswith('.json'):
            spec_dict = json_mod.loads(content)
        else:
            # Fallback: try yaml first, then json
            if yaml_mod:
                spec_dict = yaml_mod.safe_load(content)
            else:
                spec_dict = json_mod.loads(content)
    except Exception as exc:
        raise ValueError(f"Failed to parse spec file '{spec_path}': {exc}") from exc

    if not isinstance(spec_dict, dict):
        raise TypeError(f"Spec file '{spec_path}' does not contain a top-level dictionary")

    # Recursive function to flatten nested dictionaries
    def _flatten(d, parent_key='', sep='.'):
        flattened = {}
        for key, value in d.items():
            new_key = f"{parent_key}{sep}{key}" if parent_key else key
            if isinstance(value, dict):
                flattened.update(_flatten(value, new_key, sep=sep))
            else:
                flattened[new_key] = value
        return flattened

    return _flatten(spec_dict)
