def get_plugin_spec_flatten_dict(plugin_dir):
    """Creates a flat dict from the plugin spec

    The function searches ``plugin_dir`` for a JSON or YAML plugin specification
    file (``plugin.json`` or ``plugin.yaml/yml``).  The specification is parsed
    into a nested dictionary and then flattened into a single level dictionary
    with dotted keys (e.g ``{'name': 'foo', 'settings.timeout': 30}``).

    :param plugin_dir: A path to the plugin's directory (string or Path-like)
    :return: A flattened dictionary containing the plugin's properties
    :raises FileNotFoundError: If no plugin specification file can be found
    :raises ValueError: If the file cannot be parsed as JSON/YAML
    """
    import json
    import os
    import pathlib

    def _flatten_dict(d, parent_key="", result=None):
        if result is None:
            result = {}
        if isinstance(d, dict):
            for k, v in d.items():
                new_key = f"{parent_key}.{k}" if parent_key else k
                _flatten_dict(v, new_key, result)
        else:
            result[parent_key] = d
        return result

    # Search for a candidate spec file
    plugin_path = pathlib.Path(plugin_dir)
    if not plugin_path.is_dir():
        raise FileNotFoundError(f"'{plugin_dir}' is not a directory")

    spec_file = None
    # Prefer JSON, fallback to YAML
    json_candidate = plugin_path / "plugin.json"
    if json_candidate.is_file():
        spec_file = json_candidate
        file_type = "json"
    else:
        # Look for .yaml or .yml files
        yaml_candidates = list(plugin_path.glob("plugin.*yml"))
        if yaml_candidates:
            spec_file = yaml_candidates[0]
            file_type = "yaml"
        else:
            # If no obvious file, try any .json or .yaml in directory
            for ext in ("json", "yml", "yaml"):
                cands = list(plugin_path.glob(f"*.{ext}"))
                if cands:
                    spec_file = cands[0]
                    file_type = ext
                    break

    if spec_file is None or not spec_file.is_file():
        raise FileNotFoundError(f"No plugin specification file found in '{plugin_dir}'")

    # Load the spec
    try:
        with spec_file.open("r", encoding="utf-8") as fh:
            if file_type == "json":
                raw_data = json.load(fh)
            else:
                # Limited YAML support using simple front-end parser
                # We'll support only basic constructs: dicts with colon separators
                # This is a minimal parser; for full support, a YAML library is required.
                raw_text = fh.read()
                try:
                    import yaml  # type: ignore
                    raw_data = yaml.safe_load(raw_text)
                except Exception:
                    # Fallback to a naive parser (identation-based dict)
                    raw_data = {}
                    for line in raw_text.splitlines():
                        line = line.strip()
                        if not line or line.startswith("#"):
                            continue
                        if ":" in line:
                            k, v = line.split(":", 1)
                            raw_data[k.strip()] = v.strip()
    except Exception as exc:
        raise ValueError(f"Failed to parse plugin spec '{spec_file}': {exc}") from exc

    # Flatten the dictionary
    if not isinstance(raw_data, dict):
        raise ValueError(f"Plugin spec root must be a dictionary, got {type(raw_data)}")

    return _flatten_dict(raw_data)<|return|>

