def strip_root(path, root):
    """Remove root from path, throw exception on failure."""
    from pathlib import PurePath

    if not isinstance(path, str) or not isinstance(root, str):
        raise TypeError("Both 'path' and 'root' must be strings")
    if root == "":
        raise ValueError("Root cannot be an empty string")

    try:
        p = PurePath(path)
        r = PurePath(root)
        relative = p.relative_to(r)
        return str(relative)
    except ValueError:
        raise ValueError(f"root '{root}' is not a prefix of path '{path}'")<|return|>

def strip_root(path, root):
    """Remove root from path, throw exception on failure."""
    if not isinstance(path, str) or not isinstance(root, str):
        raise TypeError("Both path and root must be strings")
    if path == '' or root == '':
        raise ValueError("path and root cannot be empty strings")

    # Normalize by removing trailing slashes/backslashes
    root_norm = root.rstrip('/\\')
    path_norm = path.rstrip('/\\')

    # If the normalized path is exactly the root, return an empty string
    if path_norm == root_norm:
        return ''

    # Ensure the path starts with the root followed by a separator
    if not path_norm.startswith(root_norm):
        raise ValueError(f"Root '{root}' is not a prefix of path '{path}'")

    remaining = path_norm[len(root_norm):]
    if remaining and not (remaining[0] in ('/', '\\')):
        raise ValueError(f"Root '{root}' is not a proper directory component in path '{path}'")

    # Strip a leading separator from the remaining part
    return remaining.lstrip('/\\')
<|return|>
